programs.sol:
"""Approximate a lexical future/modal cue, strongest on will and contractions.

Use the current token and two previous tokens, reset at document boundaries.
Will is weaker after I/we and stronger after you or third-person/relative
pronouns. Smaller responses mark other auxiliaries, prospective phrases,
and selected non-English equivalents. Unrecognized tokens receive zero.
The constants are training-calibrated; this does not detect future meaning
in general (e.g. tomorrow) or model the component's small background noise.
"""
READS = ()

MODALS = {
    'would': 1.23, 'wouldn': 0.88, 'may': 0.68, 'might': 0.90,
    'shall': 0.90, 'going': 0.89, 'gonna': 1.75, 'wont': 2.19,
    'eventually': 0.59, 'upcoming': 0.74, 'forthcoming': 1.16,
    'definitely': 0.60, 'hopefully': 0.50, 'could': 0.13,
}
# Future/willingness forms: German/Dutch, Russian, Romance, and Asian languages.
FUTURE = {
    'werden': 1.07, 'wird': 0.83, 'werde': 0.81, 'wil': 0.94, 'zal': 1.38,
    'будет': 1.80, 'будут': 1.27, 'буду': 1.07,
    'será': 1.17, 'sarà': 0.99, 'seront': 0.91,
    'akan': 2.80, 'sẽ': 2.46, 'จะ': 2.07,
}


def subject_gain(word):
    if word in {'it', 'they', 'he', 'she'}:
        return 0.6
    if word in {'what', 'which', 'this', 'that', 'who', 'there'}:
        return 0.8
    return {'i': -0.6, 'we': -0.3, 'you': 1.1}.get(word, 0.0)


def chinese_future(s):
    # Recognize auxiliary 会/将, not unrelated compounds such as 社会.
    s = s.translate(str.maketrans('會將還們', '会将还们'))
    if s in {'会', '将', '将会', '都会', '我们将'}:
        return {'会': 2.7, '将': 0.87, '将会': 3.8,
                '都会': 2.9, '我们将': 1.06}[s]
    if s.startswith('将') and s[1:] in {'在', '以', '于', '是'}:
        return 2.3
    if s.endswith('会'):
        # Fused pronoun/negation/adverb + auxiliary, with weaker possibility.
        before = s[:-1]
        if before in {'不', '我', '还', '一定', '他们', '还是'}:
            return 2.4
        if before in {'你', '我们', '就', '也', '才', '肯定', '都不',
                      '是不', '并不', '永远不'}:
            return 2.05
        if before in {'可能', '总', '为什么'}:
            return 1.1
    # Auxiliary fused with a following verb, e.g. will have/cause/give.
    if s.startswith('会') and s[1:] in {'有', '影响', '出现', '导致',
                                       '使', '给', '不会', '上'}:
        return 1.9
    return 2.0 if s in {'都会有', '不会有'} else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, prev2 = carry[1:] if carry and carry[0] == doc else ('', '')
    raw = prefix.token_strings[-1]
    word = raw.strip()
    token = word.lower().replace('’', "'")
    gain = subject_gain(prev)
    value = MODALS.get(token, 0.0)
    if token == 'will':
        value = 4.9 + gain
        if word == 'Will':
            value = 4.45
        elif word == 'will' and not raw.startswith(' '):
            value = 3.57
    elif token == "'ll":
        value = 3.6 + gain
    elif token == 'won':
        value = 0.65 + 0.35 * gain
        if prev in {'has', 'have', 'had', 'was', 'were'}:
            value = 0.03
    elif token == "'d":
        value = 0.55
    elif token == "'t":
        value = 4.95 + subject_gain(prev2) if prev == 'won' else 0.0
        if prev == 'wouldn':
            value = 1.63
    elif token == 'not':
        value = {'will': 1.17, 'would': 0.28, 'might': 0.22,
                 'may': 0.11, 'shall': 0.55}.get(prev, 0.0)
    elif token == 'to':
        if prev == 'going':
            value = 2.3
        elif prev in {'likely', 'unlikely'}:
            value = 1.0
        elif prev in {'go', 'goes', 'went'}:
            value = 0.65
        elif prev in {'plan', 'plans', 'expected'}:
            value = 0.45
    elif token == 'may' and word != 'may':
        value = 0.22
    elif word in FUTURE and (raw.startswith(' ') or word == 'จะ'):
        value = FUTURE[word]
    elif token not in MODALS:
        value = chinese_future(word)
    return (doc, token, prev), float(value)

programs.luna:
"""A compact lexical approximation to an auxiliary-word signal.

“Will” gets the strong response seen for English future clauses. A few
other modal or future markers and infinitive “to” get smaller responses;
this does not try to analyze the whole sentence.
"""
READS = ()

FUTURE = {"will", "'ll", "’ll"}
OTHER_AUXILIARIES = {"would", "may", "werden", "поможет", "将", "或将"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in FUTURE:
        value = 5.0
    elif word in {"'t", "’t"} and len(prefix.token_strings) > 1:
        previous = prefix.token_strings[-2].strip().lower()
        value = 5.0 if previous in {"won", "wo"} else 0.0
    elif word == "would":
        value = 1.2
    elif word in OTHER_AUXILIARIES:
        value = 0.7
    elif word == "to":
        value = 0.6
    else:
        value = 0.0
    return None, value

programs.sol:
"""Lexical detector for tags, signatures, labels, and related marks.

These words receive negative activations, including code identifiers and some
Chinese equivalents. Case and attached punctuation change their strength.
A one-word memory handles split signatures/tagged and 'signature of'. The
-ature(s) ending also gets a weaker baseline response. Other weak, varied
token-specific responses are deliberately left at zero.
"""
READS = ()

MARKS = {'sign', 'signs', 'badge', 'badges', 'stamp', 'stamps', 'stamped',
         'seal', 'seals', 'tattoo', 'stencil', 'stickers'}
FASTENINGS = {'tie', 'ties', 'tied', 'tape', 'tab', 'tabs', 'ribbon',
              'ribbons', 'attachments', 'staples', 'tail', 'tails',
              'trailing', 'extensions'}
PUNCTUATION = '._-/\\()[]{}<>,:;\"\''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.strip(PUNCTUATION)
    w = word.lower()
    spaced = token.startswith(' ')
    value = 0.0
    if w in {'tag', 'tags'}:
        value = -3.25 if w == 'tag' else -3.8
        if raw.startswith(('_', '(', '[', '<')) or word.isupper():
            value *= 0.7
        elif spaced and word.istitle():
            value *= 0.8
        elif not spaced and word.islower() and w == 'tag':
            value += 0.65
    elif w in {'signature', 'signatures'}:
        value = -2.7 if spaced else -2.3
        value -= 0.4 * (w == 'signatures')
    elif w in {'tagged', 'tagging', 'tagname'}:
        value = -2.2
    elif w in {'label', 'labels'}:
        value = -1.3 if spaced and word.islower() else -1.05
        if raw.startswith(('_', '.', '-', '(')):
            value = -0.85
    elif w in {'signed', 'signing'}:
        value = -1.3 if spaced and word.islower() else -0.85
    elif w in {'labeled', 'labelled', 'labeling', 'labelling'}:
        value = -0.8
    elif w in MARKS or w in FASTENINGS or w in {'sig', 'unsigned'}:
        value = -0.55
    elif w in {'fingerprint', 'fingerprints', 'stuck'}:
        value = -0.9
    elif word in {'签', '簽'}:
        value = -5.6
    elif word in {'标签', '標籤'}:
        value = -4.7
    elif word in {'签名', '簽名', '签字', '簽字', '签署', '簽署', '签订'}:
        value = -2.7
    elif word in {'贴', '貼', '标记', '標記', '牌', '封', '尾', '尾巴'}:
        value = -1.0
    elif raw in {'ature', 'atures'}:
        value = -0.3 if raw == 'ature' else -0.85
        if previous.endswith('sign'):
            value = -1.0 if raw == 'ature' else -2.35
    elif raw in {'ged', 'ging', 'S'} and previous.endswith('tag'):
        value = -2.0
    elif token == ' of' and previous in {
        'signature', 'signatures', 'signing', 'tagging', 'label', 'labels'}:
        value = -0.75
    return (doc, w), value

programs.luna:
"""Recognize words for marks and labels: signatures, tags, and labels."""

import re

READS = ()

_STRONG = {"signature", "signatures", "tag", "tags"}
_MIDDLE = {"label", "labels", "sticker", "stickers", "badge", "badges"}
_LIGHT = {
    "sign", "signed", "signing", "seal", "sealed", "stamp", "stamped",
    "mark", "marked", "marking", "attachment", "attachments",
}
_WORDS = re.compile(r"[A-Za-z]+")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (doc, "")
    if doc != old_doc:
        tail = ""

    token = prefix.token_strings[-1]
    text = tail + token
    start = len(tail)
    matches = list(_WORDS.finditer(text))
    value = 0.0
    if matches and matches[-1].end() > start:
        word = matches[-1].group().lower()
        if word in _STRONG:
            value = -2.5
        elif word in _MIDDLE:
            value = -0.9
        elif word in _LIGHT:
            value = -0.55

    return (doc, text[-64:]), float(value)

programs.sol:
"""Mainly a negative lexical signal for selecting and choosing.

SELECT forms, choice/election words, and their multilingual counterparts fire
with different strengths. A selection phrase also fires on a following article
or preposition (especially 'selection of'), or on a split inflectional suffix.
State resets between documents. Formatting and inflection affect strength.
'boxed' and positive 'upon' are small additional lexical responses.
Most small, unrelated token-specific responses are deliberately omitted.
"""
from functools import cache

READS: tuple[str, ...] = ()
CONTINUATION = {
    "of": 0.66, "the": 0.35, "a": 0.19, "an": 0.27,
    "to": 0.09, "from": 0.09, "by": 0.13,
}


@cache
def selection_signal(token):
    word = token.strip().lstrip('._-/([<>\"\'').lower()
    # 'eselect' is the token-sized fragment of 'deselect'.
    if word in {'deselect', 'eselect'}:
        return -2.2
    if word.startswith(('getselected', 'isselected', 'setselected')):
        return -1.6
    if word.startswith('select'):
        if word.startswith('selected') and word != 'selected':
            return -1.6
        if word.startswith('selector') or word.startswith('selectiv'):
            return -0.9
        if word.startswith('selectable'):
            return -1.5
        if word.startswith('selection'):
            return -3.0 if token.startswith(' Selection') else -2.6
        if word == 'selected':
            if token.strip('._- ').isupper():
                return -1.75
            if token.startswith('-'):
                return -3.15
            return -2.1 if token == 'selected' else -2.4
        if word == 'selecting':
            return -2.1
        if token.strip('._- ').isupper():
            return -1.55
        if token == 'Select':
            return -2.15
        return -2.5 if token.startswith('-') else -2.0
    if word == 'chosen':
        return -1.25
    if word in {'choose', 'chooses', 'choosing'}:
        return -0.85
    if word == 'chose':
        return -0.75
    if word in {'choice', 'choices', 'pick', 'picks', 'picked', 'picking',
                'picker', 'chooser'}:
        return -0.58
    if word == 'elect':
        return -0.55 if token.strip().istitle() else -0.9
    if word in {'elected', 'election', 'الانتخابات'}:
        return -1.0
    if word in {'elections', 'electoral', 'electorate'}:
        return -0.6
    if word in {'appointed', 'nominate', 'nominated'}:
        return -0.45
    # Common token-sized fragments of selection words.
    if word in {'sel', 'lection'}:
        return -0.6 if word == 'lection' or 'S' in token else -0.25
    if word == 'sele':
        return -1.2
    if word == 'eleg':
        return -0.5
    # Chinese/Japanese: select, selected, choosing, and candidate terms.
    if word in {'选', '選'}:
        return -4.9 if word == '选' else -4.6
    if word == '精选':
        return -3.2
    if word in {'人选', '入选', '选出', '选定', '遴选', '挑选',
                '优选', '当选'}:
        return -2.6
    if word in {'选择', '選擇', '選択', '选举', '评选', '选拔', '选取',
                '选用', '选购', '首选', '選び'}:
        return -1.9
    if word.startswith('を選'):
        return -1.9
    if '选择' in word or word == '筛选':
        return -1.5
    if word in {'候选', '竞选', '选址', '遴', '挑', '择', '擇'}:
        return -1.0
    if word in {'推荐', '推薦', '选手', '选秀'}:
        return -0.6
    # Korean and Russian selection roots.
    if word in {'선', '선택'}:
        return -1.9 if token.startswith(' ') or word == '선택' else -1.5
    if word.startswith('выб'):
        return -1.2
    # Selection/choice terms in other languages.
    if word in {'sélection', 'seleccion', 'selección', 'selecion',
                'auswahl', 'انتخاب'}:
        return -1.9
    if word in {'choisir', 'choix', 'wahl', 'wyb', 'wybór', 'wybrać',
                'seç', 'seçim', 'اختيار'}:
        return -0.85
    if word in {'wäh', 'chois'}:
        return -0.6
    if word in {'chọn', 'lựa'}:
        return -1.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, previous_word = (0.0, '')
    if carry is not None and carry[0] == doc:
        previous, previous_word = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = selection_signal(token)
    if word == 'boxed':
        value = -0.73
    elif word == 'upon':
        value = 0.7 if 'Upon' in token else 0.45
    # Continue the selection phrase, but do not spread through arbitrary words.
    factor = CONTINUATION.get(word, 0.0)
    if word == 'of' and previous_word in {'choice', 'choices'}:
        factor = 1.5
    value += previous * factor
    if token in {'s', 'ed', 'ing'} and previous < 0:
        value += previous * (1.1 if previous_word == 'elect' else 0.4)
    if word == 'chose' and previous_word == 'quelque':
        value = 0.0  # French 'quelque chose' means 'something', not choosing.
    return (doc, selection_signal(token), word), float(value)

programs.luna:
"""Recognize choice and selection words, which usually produce a negative signal here."""

READS = ()

SELECTION = ("select", "selection", "selected", "selector")
CHOOSING = ("choose", "choos", "chos", "choice", "pick")
APPOINTING = ("appoint",)
ELECTING = ("election", "elections", "elect")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].lower()
    if any(stem in word for stem in SELECTION):
        return None, -1.25
    if any(stem in word for stem in CHOOSING):
        return None, -0.8
    if any(stem in word for stem in APPOINTING):
        return None, -0.5
    if any(stem in word for stem in ELECTING):
        # An isolated "elect" can be the start of an unrelated word.
        return None, -0.45 if word.strip() == "elect" else -1.15
    if any(stem in word for stem in ("выб", "选择", "選擇")):
        return None, -1.0
    return None, 0.0

programs.sol:
"""A lexical partialness detector, not a judgment about the sentence.

Strong negative cues: partial, partially, ∂, and 偏 (biased/off-centre).
Weaker negative cues: bias, incompleteness, portions, differential calculus,
restrictions, specialization and preferences.  Commission words are another
observed lexical response.  Case and word-boundary spelling alter strength.
Split Unicode characters are recognized when their final byte arrives.
"""

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    split_character = '\ufffd' in token
    if split_character:
        word = prefix.text_prefixes[-1][-1:]

    if word == 'partial':
        value = -4.3 if token == 'partial' else -6.5
    elif word in {'_partial', '.partial', 'artial'}:
        value = -4.8
    elif word == 'partially':
        value = -4.0
    elif word == '∂':
        value = -4.35 if split_character else -3.5
    elif word == 'partialeq':
        value = -1.2
    elif word == 'ially':
        value = -3.6 if previous.endswith('part') else -0.7
    elif word == 'ial' and previous.endswith('part'):
        value = -3.3
    elif word == 'ity' and previous.endswith('artial'):
        value = -1.5
    elif word == '偏':
        value = -5.1
    elif word in {'偏偏', '偏好'}:
        value = -2.3
    elif word in {'差', '残', '殘'}:
        value = -1.6  # Difference, remainder/incompleteness.
    elif word in {'偏差', '偏远', '専'}:
        value = -1.2  # Deviation, off-centre/remoteness, specialization.
    elif word in {'bias', 'biased', 'biases', 'prejud', 'prejudices',
                  'incomplete', 'impartial', 'partly'}:
        value = -0.7 if token == 'bias' else -1.5
    elif word == 'prejudice':
        value = -1.2
    elif word == 'unbiased':
        value = -0.4
    elif word in {'differential', 'ifferential'}:
        value = -1.1
    elif word in {'derivative', 'derivatives'}:
        value = -1.2 if previous == 'partial' else -0.2
    elif word in {'specialized', 'specialised', 'specializes'}:
        value = -1.0
    elif word == 'specialize':
        value = -1.3
    elif word in {'specializing', '专家', 'proportional'}:
        value = -0.7
    elif word in {'portion', 'portions', '部分', '局部', '的部分'}:
        # Chinese terms denote a part, a local part, or 'the part of'.
        value = -0.8 if '部' in word else -0.6
    elif token == ' част':
        value = -0.9  # Russian stem for a part or partial quantity.
    elif word in {'restrictions', 'precautions', 'limitations',
                  'specialist', 'specialists', 'excerpts', 'expert'}:
        value = -0.6
    elif word in {'residual', 'residuals'}:
        value = -0.5
    elif word in {'preference', 'preferences'}:
        value = -0.8
    elif word in {'commission', 'commissions', 'commissioned'}:
        value = -0.6 if token.strip()[:1].isupper() else -0.9
    else:
        value = 0.0
    return (document, word), value

programs.haiku:
"""layers.0.mlp.down_proj:263 -- a word-start feature in Japanese text.

What it responds to (read off the component's activations on training text):
- Strongly negative on a kanji that starts a word right after kana, e.g. 仕 in
  "自分で仕事" or 売 in "を売る" (about -0.36 on average, down to -2 for some).
  Kanji after kanji (the middle of a compound) stay near 0; kanji after punctuation
  or Latin text are slightly negative.
- Positive on the particle の (about +0.4) and on と, も, に, で, は, を, が, や, から
  (about +0.16), which come right before such kanji words.
- Hiragana that is not a particle is slightly negative (about -0.05).
- Replacement characters (a partial UTF-8 character) are mixed: about -0.15 inside a
  broken character, about +0.07 when one starts after ordinary text.
Everything else (English, digits, punctuation, spaces) is about 0.

The program looks at the current token and the one before it (same document only).
The values are class means fitted by least squares on 1024 training rows. On the eval
rows this table explains about 4% of the variance (correlation 0.20), so it captures
the sign and rough size of the component, not its large individual spikes.
"""

READS: tuple[str, ...] = ()

PARTICLES = {"と", "も", "に", "で", "は", "を", "が", "や", "から"}


def _is_kanji(s):
    return len(s) > 0 and all("一" <= c <= "鿿" or c in "々〆ヶ" for c in s)


def _is_hiragana(s):
    return len(s) > 0 and all("぀" <= c <= "ゟ" for c in s)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if _is_kanji(cur):
        if _is_hiragana(prev):
            value = -0.36
        elif _is_kanji(prev):
            value = 0.0
        else:
            value = -0.09
    elif cur == "の":
        value = 0.4
    elif cur in PARTICLES:
        value = 0.16
    elif _is_hiragana(cur):
        value = -0.05
    elif "�" in cur:
        value = -0.15 if "�" in prev else 0.07
    else:
        value = 0.0
    return carry, float(value)

"""Layer-0 MLP down-projection, component 264: a "modal word or the digit five" detector.

What it does: the component writes a large value into the residual stream on the token
that is a modal verb or word of possibility (English "may", "might", "could", "should",
"can", "will", "would", "must", "shall", "maybe", "perhaps", and their counterparts in
other languages such as "可能", "peut", "может", "puede"), and a moderate value on the
digit "5" and the word "five". Everywhere else it is near zero.

The strength is set per word, from the typical activation seen on training text:
"may" is strongest (about 6), "might" about 2, "could", "can", "will", "should", "would"
about 1.2 to 1.7, "maybe" and "possibly" about 1.2, "perhaps" about 0.8, and "5" about 1.2.
Being a function of the token alone, it ignores context; the carry is unused.

Read it as a lookup: a word list, not a model of meaning. Its variance explained on
training text is about 0.87 (a full per-token table would reach about 0.96).
"""

# Modal verbs and words of possibility, lower-cased, with typical activation.
MODAL = {
    "may": 6.0, "might": 2.2, "could": 1.6, "should": 1.3, "shall": 1.3, "can": 1.25,
    "will": 1.2, "would": 1.2, "must": 1.0, "ought": 0.6, "'ll": 0.75, "’ll": 0.75,
    "maybe": 1.15, "perhaps": 0.8, "possibly": 1.2,
}

# Forms whose case or script changes the strength.
SPECIAL = {"May": 2.8, "MAY": 3.7}

# Modal and number words in other languages.
FOREIGN = {
    "可能": 2.4, "peut": 1.4, "peuvent": 1.9, "puede": 1.5, "pueden": 1.5, "podem": 1.6,
    "может": 1.8, "могут": 1.7, "können": 1.0, "kann": 0.8, "kunnen": 1.0, "可以": 0.7,
    "会": 0.5, "五": 1.5, "cinco": 1.1, "fünf": 0.9,
}

# The digit five, in its usual forms.
FIVE = {"5": 1.2, "５": 1.0, "five": 1.05, "Five": 1.1}

READS: tuple[str, ...] = ()


def strength(token: str) -> float:
    """How strongly one decoded token drives the component."""
    word = token.strip()
    for table in (SPECIAL, FOREIGN, FIVE):
        if word in table:
            return table[word]
    return MODAL.get(word.lower(), 0.0)


def step(carry, prefix, upstream):
    """One position: the component's activation on the newest token."""
    return None, float(strength(prefix.token_strings[-1]))

programs.sol:
"""Approximate a mainly lexical response to Chinese 之 (literary 'of').

An initial 之 dominates short tokens. Its temporal/between/one-of forms
are weaker than its spatial forms; longer merged tokens dilute the signal.
The agent suffix 者, other Chinese relation words, formal English backward
references, and subscript/type markers have smaller responses. Everything
