programs.sol:
"""Approximate a lexical people / 'man' spelling feature.

Read only the current token. 'Man' and short '-man' fragments get the largest
values; woman, human, men and person nouns get smaller ones. The rules also
respond to man-like spellings in names, nonhuman words, and other scripts,
so this is not a semantic test for whether a person is being discussed.
Leading spaces, capitalization and fragment length modify a few strengths.
Everything outside these word families predicts zero. Token-specific nuances
and most contextual variation are deliberately omitted.
"""
READS = ()


def lexical_value(token):
    word = token.strip().lstrip('._-').lower()
    separated = token[:1].isspace()
    # English person nouns and their visible word fragments.
    if word == 'man':
        if token.strip() == 'Man':
            return 5.3
        return 4.9 if separated else 5.6
    if word == 'woman':
        return 5.2 if token.strip() == 'Woman' else 3.9
    if word == 'human':
        return 2.3
    if word in {'men', 'women', 'omen'}:
        if word == 'men':
            return 1.85 if separated else 1.35
        return 1.55
    if word in {'person', 'people', 'persons', 'humans'}:
        if word == 'person':
            return 1.2 if separated else 0.95
        return 1.25 if word == 'humans' else 0.95
    if word in {'boy', 'guy', 'lady', 'gentlemen'}:
        return 0.95
    if word in {'girl', 'husband'}:
        return 0.65
    # The spelling feature also fires in names and nonhuman words.
    if word in {'roman', 'роман'}:
        return 2.9
    if word == 'german':
        return 1.75
    if word == 'mans':
        return 3.3
    if word == 'mann':
        return 2.9 if separated else 3.3
    if word.endswith('mann'):
        return 2.1
    if word.endswith('man'):
        if not separated and len(word) <= 5:
            return 5.5 if word.startswith('e') else 3.6
        return 2.1 * min(1.0, 6.0 / len(word))
    if word.startswith(('manag', 'manipulat')):
        return 1.0 if separated else 1.4
    if word.startswith(('manual', 'manoe', 'maneuv')):
        return 1.55
    if word.startswith(('perman', 'permal')):
        return 1.9
    if word.startswith('human'):
        return 1.0
    if word.startswith('manufac'):
        return 0.5
    if word in {'mankind', 'manhattan', 'manifold', 'mane'}:
        return 1.8
    if word.startswith('man') and word not in {'many', 'manner', 'manners'}:
        return 0.6
    # Man-like spellings/transliterations, then translated person nouns.
    if word in {'ман', 'マン', '曼'}:
        return {'ман': 4.0, 'マン': 4.9, '曼': 6.3}[word]
    if word in {'мен', 'من', 'مان', '만'}:
        return 1.3
    if word == 'человек':
        return 1.7
    if word.startswith('челов'):
        return 0.8
    if word in {'homme', 'hombre'}:
        return 1.8
    if word in {'menschen', 'mensch', 'persona', 'personne', 'femme'}:
        return 0.8
    if word in {'男人', '的男人'}:
        return 2.7
    if word in {'女人', '的女人'}:
        return 2.35
    if word in {'人', '的人', '人的', 'の人'}:
        return 1.15
    if '人' in word:
        return 0.3
    if word in {'男', '女性', '男性', '管理'}:
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    return None, float(lexical_value(prefix.token_strings[-1]))

programs.haiku:
"""Person-word detector for layers.0.mlp.down_proj:267.

This component writes into the residual stream when the current token names a
person or a human being, most strongly the word "man" (and "Man", " man",
"woman", "human"). It is almost purely a function of the current token: it
ignores context and only reads the token just seen.

The program scores each token by its lowercased, space-stripped text:
  - a short table for the core person words (man, woman, men, women, human,
    person, people, boy, girl);
  - words ending in "man" (Roman, German, chairman, human, woman) get a
    medium value;
  - words ending in "men" (women, omen) get a smaller value;
  - manage-/manu- words (manager, management, manual) get a small value;
  - Chinese 人 ("person") gets a small value.
Everything else is 0. The numbers are typical activations averaged over
training text, so the output is in the component's own units.
"""

READS = ()

WORDS = {
    "man": 5.0,
    "woman": 4.0,
    "men": 1.9,
    "women": 1.7,
    "human": 2.3,
    "humans": 1.3,
    "person": 1.2,
    "persons": 0.8,
    "people": 0.9,
    "boy": 0.9,
    "girl": 0.65,
}


def level(word):
    """Activation level for one lowercased, stripped token."""
    if word in WORDS:
        return WORDS[word]
    if word.endswith("man"):
        return 2.2
    if word.endswith("men"):
        return 1.5
    if word.startswith(("manag", "manu")):
        return 1.0
    if "人" in word:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(level(word))

