programs.sol:
"""Ability/property endings, not a logical test of what is possible.

Predict a large negative signal on -able/-ible fragments, a smaller one on
whole adjectives and ability nouns, and almost zero elsewhere. Conventional
and evaluative uses have weaker responses than productive capability words.
Remember an unfinished English word to recognize split-token exceptions.
Also recognize Romance capability endings, Chinese 可 (a potential marker),
and common Chinese/Japanese can-phrases.
The numerical strengths are approximate training averages.
"""
import re

READS = ()

DIRECT_CAPABILITIES = set('''
usable readable writable searchable playable actionable callable movable
'''.split())
CONVENTIONAL_PROPERTIES = set('''
available capable reliable stable suitable comparable affordable compatible
flexible liable feasible susceptible notable acceptable sustainable nullable
portable plausible advisable accountable
'''.split())
EVALUATIVE_ADJECTIVES = set('''
valuable vulnerable desirable probable reasonable considerable remarkable
favorable favourable responsible negligible preferable profitable permissible
unreachable unpredictable unstable undesirable fashionable enjoyable charitable
miserable reputable honorable honourable adorable inevitable despicable
responsable véritable agréable unacceptable unreasonable incompatible
interchangeable equitable
'''.split())
WEAK_ENDINGS = set('''
comfortable uncomfortable incredible terrible horrible knowledgeable
vegetable enable disable cable bible
'''.split())
RELATED_PROPERTIES = set('''
relevant ready safe handy convenient practical consistent optional mobile
versatile fragile transparent responsive evident obvious apparent friendly
impressive adhesive infectious waterproof willing interactive
'''.split())


def lexical(raw, previous):
    spelling = raw.strip().strip('_-./()[]{}<>:;,\"\'')
    word = spelling.lower()
    if word == 'able':
        if raw[:1].isspace():
            return -1.35 if previous.strip().lower() in {'be', 'being'} else -2.45
        return -6.3
    if word in DIRECT_CAPABILITIES:
        return -7.2
    if word == 'visible':
        return -5.6
    if word in {'possible', 'impossible', 'unable', 'useful'}:
        return {'possible': -1.45, 'impossible': -1.1,
                'unable': -1.25, 'useful': -1.6}[word]
    if word in CONVENTIONAL_PROPERTIES:
        return -3.25
    if any(word.startswith(n) and word[len(n):] in CONVENTIONAL_PROPERTIES
           for n in ('un', 'in', 'im', 'ir')):
        return -2.0
    if word in EVALUATIVE_ADJECTIVES:
        return -1.65
    singular = word[:-1] if word.endswith('s') else word
    if singular in WEAK_ENDINGS:
        return -0.55
    if singular in {'table', 'variable', 'iptables'}:
        return -1.9 if raw == 'table' else -0.9
    if word in RELATED_PROPERTIES:
        return -1.1
    if word in {'probability', 'possibility', 'responsibility',
                'probabilities', 'possibilities', 'responsibilities'}:
        return -0.8
    if word == 'ability':
        return -1.8 if raw[:1].isspace() or spelling.istitle() else -4.35
    if word == 'ibility':
        return -2.9
    if word.endswith(('ability', 'ibility', 'abilities', 'ibilities')):
        return -2.5
    if word in {'ably', 'ibly', 'ables', 'ibles'}:
        return {'ably': -1.8, 'ibly': -2.7, 'ables': -4.45, 'ibles': -3.0}[word]
    if word in {'abile', 'ibile', 'abilité', 'abilidad', 'abilidade',
                'ável', 'ível', 'áveis', 'íveis', 'abilit', 'ibilit'}:
        return -2.6
    if word in {'uble', 'soluble'}:
        return -4.3
    if word.endswith(('able', 'ible', 'ables', 'ibles')):
        if word in {'izable', 'ifiable'}:
            return -8.0
        fragment = raw[:1].isalpha() and len(word) <= 8 and spelling.islower()
        return (-5.1 if word == 'ible' else -6.0) if fragment else -4.7
    if word.startswith(('enable', 'disable')):
        return -1.0
    if word.startswith(('可能', '不可能')):
        return -0.5
    if word.startswith(('可', '不可')) and not word.startswith('可以'):
        return -2.8
    if any(s in word for s in ('可以', '能够', '能力',
                               'できる', 'できない', 'できます')):
        return -0.9
    return 0.004


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail, previous = ('', '') if carry is None or carry[0] != document else carry[1:]
    raw = prefix.token_strings[-1]
    ending = re.search(r'[A-Za-z]+$', tail + raw)
    whole = ending.group().lower() if ending else ''
    word = raw.strip().lower()
    value = lexical(raw, previous)
    if tail and raw[:1].isalpha() and whole != word:
        if word.endswith(('able', 'ible')):
            evaluative = whole in EVALUATIVE_ADJECTIVES or any(
                whole.startswith(n) and whole[len(n):] in EVALUATIVE_ADJECTIVES
                for n in ('un', 'in', 'im', 'ir'))
            if whole in CONVENTIONAL_PROPERTIES or evaluative:
                value = -4.25 if word == 'able' else -2.8
            elif whole in WEAK_ENDINGS:
                value = -3.6 if word == 'able' else -2.3
        elif word.endswith(('ability', 'ibility')):
            if whole in {'disability', 'probability', 'possibility', 'responsibility'}:
                value = -2.5
    # Read camel-case identifiers as property words, too.
    split = re.sub(r'([a-z])([A-Z])', r'\1 \2', raw)
    if split != raw:
        value = min(lexical(' ' + part, previous) for part in split.split())
    return (document, whole[-80:], raw), float(value)

