# 'still', and related intensifiers in several languages.
PARITY_AND_FOCUS = {
    'даже': 6.4, '甚至': 4.9, '甚至是': 3.75,
    'sogar': 5.1, 'nawet': 3.8, 'incluso': 3.6,
    'même': 2.2, 'även': 2.1, 'mesmo': 1.5,
    ' حتى': 1.8, ' anche': 1.3,
