FOCUS_WORDS = {'just', 'both', 'either', 'neither', 'ever', 'regardless'}
NEGATION = re.compile(r"(?:\bnot|\bcannot|n['’]t)$")
UNCERTAINTY = re.compile(r'\b(?:or|may|might|could|would|maybe|perhaps|without)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    # Separate punctuation attached to these short lexical words, not pieces
    # buried inside longer words such as 'seven' or 'prevent'.
    bare = word.lstrip('_.-/—(["\'')
