        if word == '_odd':
            value = 3.65
    elif word in CHINESE_PARITY:
        value = CHINESE_PARITY[word]
    elif token.strip() == 'Auch':
        value = 1.5
    elif token.lower() in PARITY_AND_FOCUS:
        value = PARITY_AND_FOCUS[token.lower()]
    elif word in PARITY_AND_FOCUS:
        value = PARITY_AND_FOCUS[word]
    elif word in FOCUS_WORDS:
        value = 0.95
    elif word == 'especially':
        value = 1.3
    elif word in {'evening', 'evenings'}:
        value = 1.55
    elif word == 'eve':
        value = 1.3 if token == ' eve' else 0.45
    elif bare in {'event', 'eventual', 'eventually'}:
        value = 0.9
    elif bare == 'events':
        value = 0.7
    elif word in {'evenly', 'uneven'}:
        value = 2.45
    elif word == 'oddly':
        value = 3.0
    elif word == 'rarely':
        value = 0.6
    elif word in {'symmetric', 'symmetry', 'parity', 'odds'}:
        value = 0.55
    elif word == 'async':
