"""A left-boundary signal for unspaced, vowel-initial word pieces.

Short nasal syllables (in/im/en/em/un) and related prefix fragments are
negative at a new word or morpheme, and more positive when completing a
consonant-heavy piece. Vowels in the preceding token weaken continuation.
Capitalized In, punctuation-attached in, and Russian от/об have explicit
rules. Other space-prefixed words and most longer tokens predict zero.

The numbers are approximate training-data levels, not exact lexical
responses. Only the preceding token is remembered, within each document.
"""
import re
import unicodedata

READS = ()
VOWELS = frozenset('aeiou')
CYRILLIC_VOWELS = frozenset('аеёиоуыэюя')
MORPHEME_STARTS = frozenset((
    're', 'un', 'dis', 'mis', 'non', 'co', 'pre', 'super', 'here', 'there',
    'self', 'immuno', 'auto', 'anti', 'micro', 'macro', 'pseudo', 'hydro',
    'photo', 'neuro', 'mono', 'poly', 'bio', 'geo', 'thermo', 'psycho',
))
LONG_PREFIXES = frozenset((
    'under', 'inter', 'into', 'inner', 'init', 'over', 'out',
))
ENDINGS = frozenset((
    'ing', 'ings', 'ingt', 'ung', 'ungs', 'ink', 'inks', 'ens', 'unt', 'unk',
))
# Each profile: fresh onset, consonant continuation, penalty per prior vowel.
SHORT_SYLLABLES = {
    'in': (-1.10, 0.78, 0.33),
    'im': (-1.40, 0.20, 0.37),
    'en': (-1.05, 0.30, 0.20),
    'em': (-0.60, 0.17, 0.15),
    'un': (-0.98, 0.52, 0.25),
    'ex': (-0.72, 1.00, 0.48),
    'ob': (-1.05, 0.32, 0.25),
    'ass': (-0.92, 0.50, 0.20),
    'att': (-0.92, 0.50, 0.20),
    'от': (-0.82, 0.54, 0.40),
    'об': (-0.50, 0.40, 0.75),
}


def syllable_profile(word):
    if word in SHORT_SYLLABLES:
        return SHORT_SYLLABLES[word]
    if word in ENDINGS:
        return -0.65, 0.06, 0.03
    if word in LONG_PREFIXES:
        return -0.40, 0.90, 0.35
    if re.fullmatch('in[cdfghmnqstv]|im[bmp]|in(st|tr|ts)', word):
        if word in {'int', 'inst'}:
            return -0.58, 1.00, 0.45
        return -0.58, 0.82, 0.38
    if re.fullmatch('en[cdgpt]|em[bp]|un[cdfhs]', word):
        if word == 'end':
            return -0.05, 0.28, 0.10
        if word == 'ent':
            return -1.00, 0.20, 0.10
        return -0.60, 0.52, 0.22
    if re.fullmatch('[ao]n[cgst]', word):
        return -0.50, 0.0, 0.0
    if word in {'ab', 'ac', 'ad', 'ag', 'ap', 'as', 'at', 'op'}:
        return -0.57, 0.09, 0.10
    if re.fullmatch(r'a([cfpst])\1|off|err', word):
        return -0.55, 0.50, 0.22
    if re.fullmatch('[aeiou][bcdfghjklmnpqrstvwxyz]{1,3}', word):
        return -0.12, 0.0, 0.0
    return None


def response(s, previous):
    word = s.lower()
    prev = ''.join(c for c in unicodedata.normalize('NFD', previous.lower())
                   if not unicodedata.combining(c)).strip()
    last = previous[-1:]
    script = 'LATIN' if word.isascii() else 'CYRILLIC'
    boundary = (not last or not last.isalpha() or
                not unicodedata.name(last, '').startswith(script))

    if s in {' In', 'In'}:
        if '\\' in previous:
            return -0.40
        return -0.52 if boundary else (-0.35 if s[0] == ' ' else -0.20)
    if s == ' IN':
        return -0.43
    if len(s) > 2 and s[0] in '(/._-' and word[1:] == 'in':
        return -0.30
    if not s.isalpha() or s.istitle():
        return 0.0
    profile = syllable_profile(word)
    if profile is None:
        return 0.0
    onset, continuation, penalty = profile

    if '\\' in previous:
        return onset * 0.16
    if boundary or prev in MORPHEME_STARTS:
        if not previous:
            return onset * 0.50
        if boundary and last not in '\"\'([{“‘' and '\n' not in previous:
            return onset * 0.75
        return onset
    vowel_letters = VOWELS if word.isascii() else CYRILLIC_VOWELS
    vowels = min(2, sum(c in vowel_letters for c in prev))
    value = continuation - penalty * vowels
    if prev[-1:] in vowel_letters and penalty:
        value -= 0.12
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, token), float(response(token, previous))

