YER = "ъЪ"
GO_MARKERS = ("func", "package", "import", ":=", ".go", "return", "err")
GO_STRUCTURE = {"\t", "\treturn", " func", "func", "//", " {\n", "/pkg", '"', "Marshal", ".New"}
GO_WORDS = {".go", "go", " go", "/pkg", " func"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "in_yer_word": False, "go_markers": 0}
    # Track whether the letter-run ending at this token contains ъ.
    for ch in s:
        if ch.isalpha():
            carry["in_yer_word"] = carry["in_yer_word"] or ch in YER
        else:
            carry["in_yer_word"] = False
    if carry["in_yer_word"]:
        value = 4.0
    elif carry["go_markers"] >= 2 and s in GO_STRUCTURE:
        value = 1.0
    elif s in GO_WORDS:
        value = 2.0
    else:
        value = 0.0
    if any(m in s for m in GO_MARKERS):
        carry["go_markers"] += 1
    return carry, value

