"""Conservative markers for words naming a personal trait or quality."""

READS = ()

TRAIT_WORDS = {
    "brave", "bravery", "intelligent", "capable", "confidence", "confident",
    "knowledge", "influential", "neutral", "speed", "lazy", "traits",
    "strange", "calm", "jealousy", "outspoken", "open", "manner",
    "self-control", "self-awareness", "sensitive", "strong",
