def step(carry, prefix, upstream):
    doc, tail = carry if carry is not None else (None, "")
    current_doc = prefix.document_ids[-1]
    if current_doc != doc:
        tail = ""

    piece = prefix.token_strings[-1]
    fragment = piece.rsplit(None, 1)[-1] if piece.strip() else ""
    if any(ch.isspace() for ch in piece) or not piece[:1].isalpha():
        word = fragment
    else:
        word = tail + fragment
    word = "".join(ch for ch in word.lower() if ch.isalpha() or ch == "-")
    last_word = word.rsplit("-", 1)[-1]

    value = 0.14 if word in TRAIT_WORDS or last_word in TRAIT_WORDS else 0.0
    next_tail = last_word if len(last_word) < 40 else ""
