programs.haiku:
"""Layer-0 MLP unit 277 (component layers.0.mlp.down_proj:277): inline symbols in running prose.

The component fires on punctuation and symbols that are written inline inside an English
sentence, right after a word or a number: "and/or", "R&D", "word [1]", "some 50%",
"Anderson Kill [as a paralegal]", "A | B". It is strongest for "%" after a number and for
"/or" in "and/or", then "[", "&", "]", "|", "/", and weaker for "+", "\\", "@", ">", "=".
The same symbols in code, markup or lists (where the text around them is mostly symbols,
not words) barely fire. So the program scales each symbol's strength by how prose-like
the previous 12 tokens are: the share of them that are words or numbers.

Two small negative cases: a hyphen and 's after a word in prose are slightly negative.
A run of 4+ spaces after a blank token fires a little. Everything else is 0.

It reads only the current token and the 12 before it, within the same document.
"""

import re

READS = ()

WORD = re.compile(r"\s?[A-Za-z]+")
NUMBER = re.compile(r"\s?[0-9]+")

# typical activation of each kind of symbol right after a word, in fully prose-like text
STRENGTH = {
    "pct": 0.45,
    "bracket": 0.31,
    "amp": 0.29,
    "slash": 0.17,
    "pipe": 0.10,
    "eq": 0.085,
    "dash": -0.055,
    "possessive": -0.03,
}
BRACKETS = ("[", "]", "].", "[]")
PIPES = ("|", "\\", "+", "@", ">")
WINDOW = 12


def kind(token):
    """Which kind of symbol the token is, or None."""
    if "%" in token:
        return "pct"
    bare = token.strip()
    if bare in BRACKETS:
        return "bracket"
    if "&" in token:
        return "amp"
    if "/" in token:
        return "slash"
    if bare in PIPES:
        return "pipe"
    if bare == "=":
        return "eq"
    if bare == "-":
        return "dash"
    if token in ("'s", "’s"):
        return "possessive"
    return None


def is_word_or_number(token):
    return WORD.fullmatch(token) is not None or NUMBER.fullmatch(token) is not None


def prose_share(prefix):
    """Share of the previous WINDOW tokens (same document) that are words or numbers."""
    strings = prefix.token_strings
    docs = prefix.document_ids
    now = docs[-1]
    before = [i for i in range(max(0, len(strings) - 1 - WINDOW), len(strings) - 1) if docs[i] == now]
    if not before:
        return 0.0
    return sum(is_word_or_number(strings[i]) for i in before) / len(before)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = prefix.token_strings[-2] if same_doc else None
    after_text = previous is not None and is_word_or_number(previous)
    if token == "/or":
        return carry, (0.9 * prose_share(prefix) if after_text else 0.0)
    k = kind(token)
    if k is None:
        if token.strip() == "" and len(token) >= 4 and previous is not None and previous.strip() == "":
            return carry, 0.10
        return carry, 0.0
    strength = STRENGTH[k]
    if k == "pct" and after_text:
        strength = 0.45
    if after_text:
        return carry, strength * prose_share(prefix)
    return carry, 0.3 * strength * prose_share(prefix)

programs.luna:
"""Give larger estimates for references, numerical notation, and formatting marks.

A percent sign following a numeral is the clearest cue. Brackets, slashes, and small
operators are weaker cues; ordinary text is assigned zero. This uses only nearby text
and captures likely cases without modeling the component's full context sensitivity.
"""
READS = ()

OTHER_MARKS = {"[", "]", "/", "+", "=", ">", "&"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = token.strip()
    if mark == "%" and len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].rstrip()
            if previous and previous[-1].isdigit():
                return None, 0.30
    if mark in OTHER_MARKS:
        return None, 0.06
    if mark in ("-", "\u00ad", "–", "—"):
        return None, -0.03
    if token and not token.strip():
        if "\n" in token or "\r" in token:
            return None, -0.03
        if "\t" in token or len(token) >= 2:
            return None, 0.03
    return None, 0.0

