    (1.4, {'racial', 'lgbtq'}),
    (1.1, {'genre', 'ethnic', 'parity'}),
    (0.9, {'nationality', 'sexy'}),
    (0.8, {'spouse', 'feminist', 'heterosexual'}),
    (0.7, {'birth', 'pregnancy', 'hormone', 'hormones',
