    (0.55, {'race', 'races', 'religion', 'religions', 'males'}),
    (0.5, {'ages', 'nude', 'intercourse', 'marital'}),
    (0.4, {'colour', 'male', 'profession'}),
    (0.3, {'blood', 'hair', 'aged'}),
    (0.2, {'female', 'females', 'color', 'births'}),
)
