SEX_WORDS = {"sex", "sexe", "sexo", "-sex"}
SEXUAL = {"sexual", "sexually", "sexuality", "sexy", "homosexual", "lesbian", "feminist", "feminism"}
DEMOGRAPHIC = {
    "age", "ages", "birth", "race", "racial", "ethnic", "ethnicity", "genre", "genres",
    "hex", "parity", "pregnancy", "spouse", "masculine", "婚", "婚姻", "配偶", "男女", "民族", "肤色",
}
WEAK = {"male", "males", "female", "females", "religion", "blood", "glucose", "hair", "男", "女"}


def step(carry, prefix, upstream):
    """Predicted activation at the newest token: a graded negative value for sex and gender words."""
    w = prefix.token_strings[-1].strip().lower()
    if "gender" in w or w == "性别":
        return None, -5.5
    if w in SEX_WORDS:
        return None, -3.5
    if "sex" in w:
        return None, -1.5
    if w in ("ender", "enders", "hex"):
        return None, -1.2
    if w in DEMOGRAPHIC or w in SEXUAL:
        return None, -1.0
    if w in WEAK:
        return None, -0.4
    return None, 0.0

