            return -0.02
        if p in INTRODUCERS:
            return 0.17
        if p in TYPE | FORMAT | {'mode', 'date', 'time', 'source'}:
            return -0.75
        return -0.12 if s == '：' else (-0.35 if "'" in s else -0.23)
    if s in ('://', '::'):
        return -0.03
    if s.startswith(':\\'):
        return -0.13
    if s.startswith(':'):
        return -0.36 if '\n' not in token else 0.0

    w = name(token)
    if w in ('mode', 'modes'):
        if p.endswith(('set', 'color', 'display', 'fetch')):
            return -2.60
        return -0.51 if spaced else (-1.65 if s.startswith(('_', 'M')) else -0.90)
    if w in ('encoding', 'charset'):
        return -0.55 if s.startswith('.') else (-0.75 if spaced else -1.20)
    if w in ('type', 'types', 'dtype'):
        if s.startswith('-T'):
            return -1.45
        if s.startswith('-t'):
            return -0.04
        if s.startswith(('_', '.')):
            return -0.32
        if spaced:
            return 0.15 if p in DETERMINERS else -0.08
        return -0.50 if s[:1].isupper() else -0.27
    if w in ('kind', 'method', 'direction', 'strategy', 'policy', 'enabled'):
        return (-0.18 if w == 'direction' else 0.0) if spaced else -0.50
    if w in ('level', 'levels', 'indent', 'specifier', 'fmt', 'scheme'):
        return -0.15 if spaced else -0.30
    if s.endswith(('Type', 'Kind', 'Encoding', 'Mode')):
        return -0.65
    if s.startswith('-') and w in DISPLAY:
        if p == 'font':
            return -2.35 if w == 'size' else -1.65
        return -1.25 if p in ('text', 'padding', 'max', 'min') else -0.40
    if s in ('"', "'") and '=' in previous:
        return -0.32
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    return (doc, token), response(token, previous, first)

