"""Recognize plural-looking noun endings in the current word piece.

The component is most active on nouns with visible plural morphology. The
strongest families here are -ies and -ments, followed by -ions and similar
noun endings; ordinary final -s is a weaker clue. Other pieces get zero.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
