programs.sol:
"""Responses to chat boundaries, especially the start of a user's message.

Training examples show a strong pulse at the newline ending a user header.
The program makes this pulse smaller in the first four document tokens. Assistant-header and end-of-message newlines
are negative, especially early in the document. Tool and thinking tags
have smaller signed responses. Ordinary text is left near zero; its lexical variation is not modeled.
"""
READS = ()

# The formatting tags are a single, recognizable vocabulary of chat controls.
TAG_RESPONSE = {
    '<|im_end|>': -0.036,
    '<tool_call>': 0.066,
    '</tool_call>': -0.015,
    '<tool_response>': -0.026,
    '</tool_response>': 0.105,
    '<think>': 0.110,
    '</think>': 0.003,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous, before = 0, '', ''
    else:
        _, age, previous, before = carry
        age += 1
    token = prefix.token_strings[-1]
    value = TAG_RESPONSE.get(token, -0.001)

    if token == '\n':
        if previous == 'user' and before == '<|im_start|>':
            value = 0.122 if age < 4 else 0.275
        elif previous == 'assistant' and before == '<|im_start|>':
            value = -0.080 if age < 64 else -0.015
        elif previous == '<tool_response>':
            value = 0.040 if age < 20 else 0.125
        elif previous == '<|im_end|>':
            value = -0.060 if age < 64 else -0.018
        elif previous == '<tool_call>':
            value = -0.021
    elif token == '\n\n':
        value = -0.014
        if previous == '<think>':
            value = -0.076
        elif previous == '</think>':
            value = -0.030
    elif token == '<|im_start|>':
        value = 0.015 if age == 0 else -0.034

    return (doc, age, token, previous), value

programs.haiku:
"""Layer 0, MLP down_proj, component 286 (a rank-one piece of the MLP output).

What it does, in plain terms: this component is a weak, mostly token-specific
"lexical" feature. It is near zero almost everywhere (std about 0.03), and its
clearest, largest responses are on a few chat-format and tool-format tokens:

  * the newline right after the word "user" in a chat turn
    ("<|im_start|>user\\n"): strongly positive, about +0.23;
  * the token right after a "<tool_response>" tag (usually its newline): about +0.12;
  * the tag-opening tokens "</tool_response>", "<think>", "<tool_call>": about +0.10;
  * the chat/tool markers "<|im_start|>", "<|im_end|>", "<tool_response>": slightly
    negative, about -0.03;
  * other newlines: about zero.

Everything else is predicted as 0. The program tracks the document boundary the
way the model does: the previous token is taken as empty at the first token of a
document. It is causal: it reads only the prefix up to the current token.

What it misses: most of the variance is spread over thousands of ordinary words
and subwords whose signs differ (for example " tsp", "console" are negative, "line",
".md" positive). Those are a per-token lookup, not a concept, so they are left out.
"""

READS = ()

# Values (activation units) for each rule, rounded from the fit on training rows.
USER_NEWLINE = 0.23
AFTER_TOOL_RESPONSE = 0.12
OPEN_TAGS = {"</tool_response>", "<think>", "<tool_call>"}
MARKERS = {"<|im_start|>", "<|im_end|>", "<tool_response>"}
OPEN_TAG_VALUE = 0.10
MARKER_VALUE = -0.03


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    if tok == "\n" and prev == "user":
        value = USER_NEWLINE
    elif prev == "<tool_response>":
        value = AFTER_TOOL_RESPONSE
    elif tok in OPEN_TAGS:
        value = OPEN_TAG_VALUE
    elif tok in MARKERS:
        value = MARKER_VALUE
    else:
        value = 0.0
    return carry, float(value)


if __name__ == "__main__":
    # Quick look: print the rule value at each token of a made-up chat line.
    class _P:
        pass
    toks = ["<|im_start|>", "user", "\n", "Hello", "<|im_end|>"]
    for i in range(len(toks)):
        p = _P()
        p.token_strings = toks[: i + 1]
        p.document_ids = [0] * (i + 1)
        print(repr(toks[i]), step(None, p, {})[1])

programs.sol:
"""A MIN-spelling detector with weaker MAX and lower-bound associations.

The fragment 'min' is strongest, including in code. Longer MIN families
(minimal, minutes, minerals, minister, administration) respond less.
This is not just a mathematical-minimum detector. Short continuations of
split words and the phrases 'at least'/'Prime Minister' are handled too.
Chinese bounds/mining terms and other MIN-like spellings are included.
"""

READS = ()

# Longest matching word stem wins.
STEMS = {
    'minimum': 4.1, 'minimal': 3.6, 'minimalist': 2.35,
    'minim': 2.6, 'minimized': 3.1, 'minimizing': 2.15,
    'mini': 3.0, 'miniature': 1.8,
    'minut': 2.0, 'minutes': 2.55,
    'mineral': 3.5, 'mining': 2.6, 'miner': 2.5,
    'mine': 1.5, 'mines': 2.5,
    'minist': 3.1, 'minat': 1.1, 'minor': 1.8, 'minorit': 1.3,
    'minus': 1.4, 'minnesota': 1.8,
    'admin': 4.1, 'administr': 2.3, 'administrative': 2.5,
    'administrator': 2.0, 'administer': 1.9,
    'termin': 1.4, 'terminal': 0.55, 'terminat': 0.6,
    'remind': 0.85, 'reminded': 1.2, 'reminding': 0.5,
    'maxim': 0.9, 'maximum': 1.2, 'maximal': 1.2,
}
STEMS = sorted(STEMS.items(), key=lambda pair: -len(pair[0]))
FRAGMENTS = {
    'amin': 2.4, 'emin': 2.5, 'imin': 2.7, 'omin': 2.5,
    'umin': 1.5, 'mina': 3.0, 'amine': 0.95, 'minmax': 2.5,
    'mín': 2.65, 'mínimo': 1.9, 'mínima': 1.9,
}
BOUNDS = {
    'smallest': 1.2, 'lowest': 0.6, 'youngest': 0.8,
    'approximately': 0.5, 'approximate': 0.85, 'approx': 0.75,
}
# Chinese: small/least, administration, mining/minerals, minutes/seconds.
# Cyrillic: MIN, minimal, minister, minutes, MAX.
# Japanese/Korean: MINI/MIN spellings.
OTHER_SCRIPTS = {
    '最小': 3.5, '最低': 1.7, '至少': 1.75, '小': 0.6, '的小': 0.65,
    '行政': 2.6, '矿': 5.85, '礦': 5.85,
    '矿物质': 3.1, '矿业': 3.6, '矿区': 2.7,
    '分钟': 1.8, '分鐘': 1.75, '秒': 0.7,
    'мин': 3.4, 'минималь': 3.1, 'министр': 2.4,
    'минут': 1.3, 'максималь': 1.5, 'минист': 1.8,
    'ミニ': 2.5, '민': 1.05,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, partial = '', ''
    else:
        previous, partial = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._/\\-(=[:').lower()
    value = FRAGMENTS.get(
        word, BOUNDS.get(word, OTHER_SCRIPTS.get(word, 0.0))
    )
    for stem, gain in STEMS:
        if word.startswith(stem):
            value = gain
            break

    bare = token.strip().lstrip('._/\\-(=[:')
    if bare.startswith(('min', 'Min')) and bare[3:4].isupper():
        value = 3.0

    if word in ('min', 'mins'):
        value = 5.0 if word == 'min' else 3.9
        if token.startswith(('_', '/')) or token == 'MIN':
            value = 4.25
        elif token == '.min':
            value = 5.4
    elif word == 'minimum' and not token[:1].isspace():
        value = 3.5
    elif word == 'max':
        value = 0.95 if token.startswith('_') else 1.45
    elif word == 'least':
        value = 1.5 if previous == 'at' else 0.65
        if previous == 'not':
            value = 0.33
    elif word == 'minister':
        value = 3.5
        if previous == 'prime':
            value = 2.5 if bare.islower() else 1.8
    elif word == 'of' and previous in ('min', 'minimum', 'max', 'maximum'):
        value = 1.3 if previous.startswith('min') else 0.4
    elif word == 'seconds':
        value = 0.95 if token.startswith('.') else 0.65
    elif word == 'main':
        value = 0.95 if token.startswith('/') else 0.2

    # Spellings continued in the next token, not numerical reasoning.
    if token.isalpha() and value == 0.0:
        if partial.endswith(('min', 'admin')):
            value = 2.3 if word in ('ister', 'imum', 'eral') else 1.0
            if word in ('im', 'imize', 'imal', 'istry', 'ing'):
                value = 1.75
        elif partial.endswith(('minim', 'administr')):
            value = 1.3

    if '\ufffd' in token:
        value = OTHER_SCRIPTS.get(prefix.text_prefixes[-1][-1:], value)
    partial = (partial + word)[-32:] if token.isalpha() else word
    if not token[-1:].isalpha():
        partial = ''
    return (doc, word, partial), float(value)

programs.luna:
"""A compact guess for min/max, least, and small-value cues."""
READS = ()

LEAST_WORDS = ("least",)
LOW_WORDS = ("lowest", "low", "small", "tiny")
PUNCTUATION = " \t\r\n.,;:!?()[]{}\"'`"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1].lower()
    old_doc, tail = carry if carry is not None else (None, "")
    if doc != old_doc:
        tail = ""
    joined = tail + token
    min_hit = "min" in token or (
        "min" in joined and "min" not in tail and "min" not in token
    )
    max_hit = "max" in token or (
        "max" in joined and "max" not in tail and "max" not in token
    )
    word = token.strip(PUNCTUATION)
    if min_hit:
        value = 2.4
    elif max_hit:
        value = 1.5
    elif word in LEAST_WORDS:
        value = 1.5
    elif word in LOW_WORDS or "小" in token:
        value = 0.65
    else:
        value = 0.0
    return (doc, joined[-4:]), value

programs.sol:
"""Predict a lexical response to second-person address: chiefly 'you'/'your'.

Selected pronouns in several languages also respond, with smaller responses
for students/learners and Chinese 'together'/'everyone' expressions. The
Chinese title-opening bracket is a separate lexical response.

Case, leading space and the preceding token adjust the response. Repeated
'you'/'your' within the last 20 tokens are weaker than a fresh mention.
Everything else is approximated by zero; this is not semantic role parsing.
"""

READS = ()

# Second-person forms; values are activation sizes, not token identifiers.
ADDRESS = {
    'yours': 0.98, 'yourself': 0.70, 'yourselves': 0.70,
    'vous': 0.88, 'votre': 0.73, 'vos': 0.36,
    'você': 1.13, 'vocês': 1.13, 'bạn': 1.02,
    'вы': 0.49, 'вас': 0.83, 'вам': 0.89, 'ваш': 0.87,
    'ваши': 0.44, 'вашего': 0.64,
    'usted': 0.64, 'tu': 0.20, 'tú': 0.12,
    'ты': 0.26, 'тебя': 0.52, 'тебе': 0.52,
    'あなた': 1.17,
}
CHINESE_ADDRESS = {
    '你': 1.58, '您': 1.19,
    '你的': 1.18, '您的': 0.93, '你们': 1.15, '你們': 0.98,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    recent = carry[2] if carry is not None and carry[0] == doc else ()
    value = 0.0
    if lower == 'you':
        value = 1.52 if spaced else 1.40
        if word == 'You':
            value = 1.41 if spaced else 1.23
        elif word == 'YOU' and not spaced:
            value = 1.19
        if previous in {'help', 'helps'}:
            value += 0.60
        elif previous in {'guide', 'guides'}:
            value += 0.85
        elif previous in {'how', 'why'}:
            value += 0.48
        elif previous in {'as', 'where', 'while'}:
            value += 0.34
        elif previous in {'if', 'unless', 'thank'}:
            value -= 0.30
        elif previous in {'can', 'could', 'do', 'are'}:
            value -= 0.25
        elif previous in {'and', 'or', 'then'}:
            value -= 0.12
    elif lower == 'your':
        value = 1.35 if spaced else 1.25
    elif word in CHINESE_ADDRESS:
        value = CHINESE_ADDRESS[word]
    elif '你' in word:
        value = 1.00
    elif '您' in word:
        value = 0.72
    elif lower in ADDRESS:
        value = ADDRESS[lower]
        if word[:1].isupper():
            value *= 0.85
        if not spaced and lower != 'あなた':
            value *= 0.75
    elif lower in {'students', 'learners'}:
        value = 0.58
    elif lower in {'student', 'learner', 'pupils'}:
        value = 0.23
    elif word in {'学生', '同学们', '共同'}:
        value = 0.40
    elif '大家' in word:
        value = 0.62
    elif word in {'一起', '一起来', '一同'}:
        value = 0.80
    elif '《' in word:
        value = 0.60
    if lower in {'you', 'your'} and previous:
        # Reduce repeated second-person forms in the recent token window.
        value += (0.12, -0.065, -0.14, -0.19)[min(3, sum(recent))]
    recent = (recent + (lower in {'you', 'your'},))[-20:]
    return (doc, lower, recent), float(value)

programs.haiku:
"""Second-person address detector (layer 0 MLP, unit 288).

This unit fires on the words a writer uses to address the reader directly:

* English "you", "your", "yours", "yourself": strongest on "you" and "your"
  (about 1.5 and 1.35), a bit weaker on "yourself" and "yours".
* The same idea in other languages: any token containing 你 or 您 (你, 您, 你们,
  如果你, 为你, ...) and words like vous, bạn, você, あなた, вы, вас, ваш.
  Translated "you" is weaker than English, and the formal forms (вы, vous)
  are weaker still.
* Group address such as "students" or 大家 ("everyone"), weaker again.

Within "you" and "your" the level depends a little on the word before: higher
after verbs like help, show, see, how, as, where; lower after if, thank, can, do,
are (questions and conditionals).

The program reads the current token and the one before it. It matches their
decoded text, lowercased and stripped of spaces, against the word lists below.
Everything else predicts 0.
"""

READS = ()

EN_YOU = {"you": 1.5, "your": 1.35, "yours": 1.0, "yourself": 0.7, "yourselves": 0.7}
OTHER_YOU = {
    "您的": 1.0, "您": 1.2, "你的": 1.3, "你们": 1.2, "你們": 1.0,
    "bạn": 1.0, "você": 1.2, "vous": 0.9, "votre": 0.7, "vos": 0.4,
    "あなた": 1.1, "당신": 0.9, "あなたの": 0.85, "вы": 0.5, "вас": 0.9, "вам": 0.9, "ваш": 0.9, "ваши": 0.4,
    "usted": 0.6, "anda": 0.6, "ınız": 0.6, "тебя": 0.5,
}
GROUP_ADDRESS = {"students": 0.6, "student": 0.2, "learners": 0.5, "大家": 0.6, "同学们": 0.55,
                 "kids": 0.3, "readers": 0.2}
HELPING_BEFORE = {"help", "helps", "how", "as", "where", "see", "show", "what", "want", "when"}
QUESTION_BEFORE = {"if", "thank", "can", "do", "are", "have", "and", "or"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[prefix.position]
    word = raw.strip().lower()
    if word in ("you", "your") and prefix.position > 0:
        before = prefix.token_strings[prefix.position - 1].strip().lower()
        if before in HELPING_BEFORE:
            return None, 1.8 if word == "you" else 1.6
        if before in QUESTION_BEFORE:
            return None, 1.2 if word == "you" else 1.1
    if "你" in raw or "您" in raw:
        return None, 1.2
    for table in (EN_YOU, OTHER_YOU, GROUP_ADDRESS):
        if word in table:
            return None, table[word]
    return None, 0.0

programs.sol:
"""Predict horizontal-padding activations from the current gap and its line.

Large negative predictions mark gaps after filenames, words, and colons.
Indentation is near zero; mixed tab/space indentation can be positive.
Long prose-like lines, comment margins, and escaped code get weaker responses.
Very long gaps fade; trailing newlines and nonbreaking spaces are attenuated.
These are fitted layout heuristics, not predictions of all lexical variation.
State keeps only the last 256 characters of the line and the previous token,
and resets at document boundaries. Non-whitespace tokens return zero.
"""
import math

READS: tuple[str, ...] = ()
FILE_EXTENSIONS = set('''
    c h cc cpp hpp cs go rs py js ts jsx tsx java rb php sh sql
    md rst txt json yaml yml toml xml html css csv log ini cfg
    mod sum lock conf config example tmpl dockerfile makefile
'''.split())
PROJECT_FILES = {
    'LICENSE', 'README', 'Makefile', 'Dockerfile', 'CONTRIBUTING',
    'CHANGELOG', 'AUTHORS', 'NOTICE', 'OWNERS', 'CODE_OF_CONDUCT',
}
COMMENT_MARKERS = {'#', '//', '///', '*', '/*', '--', '-'}


def gap_response(last, width, line):
    """Typical activation for a separate run of spaces after an item."""
    long_line = len(line) > 140
    extension = last.rsplit('.', 1)[-1].lower()
    filename = ('.' in last and extension in FILE_EXTENSIONS)
    filename |= last in PROJECT_FILES
    filename |= (last.startswith('.') and last[1:].isalpha())
    if line.strip() in COMMENT_MARKERS:
        value = 0.02 if width == 1 else -0.12
    elif filename:
        value = (-0.36 if width == 1 else -0.75)
        value *= 0.75 if long_line else 1.0
    elif '/' in last and any(c.isalpha() for c in last):
        value = -0.06 if width == 1 else -min(0.55, 0.25 + 0.035 * width)
    elif last.endswith(':'):
        value = -0.12 if width == 1 else -min(0.55, 0.38 + 0.035 * width)
    elif last[-1].isdigit():
        value = -0.012 if width == 1 else -min(0.30, 0.085 * width)
    elif last.endswith('.'):
        value = -0.05 if width == 1 else -0.32
        if long_line:
            value = 0.05 if width == 1 else 0.12
    elif last[-1].isalpha() or last[-1] == '_':
        value = -0.04 if width == 1 else -min(0.64, 0.20 + 0.10 * width)
    elif last[-1] in "\"'`":
        value = -0.08 if width == 1 else -0.25
    else:
        value = -0.02 if width == 1 else -min(0.34, 0.19 + 0.025 * width)
    if long_line and not filename and not last.endswith('.'):
        value = 0.04 if width == 1 else 0.04 + value * 0.28
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, line, previous = carry if carry and carry[0] == doc else (doc, '', '')
    token = prefix.token_strings[-1]
    horizontal = token.rstrip('\r\n')
    spaces = horizontal.count(' ') + horizontal.count('\xa0')
    tabs = horizontal.count('\t')
    value = 0.0
    if horizontal and spaces + tabs == len(horizontal):
        words = line.split()
        inline = bool(words) and not line.strip().isdigit()
        if tabs and spaces:
            value = 0.035 if words else 0.17
        elif not inline:
            value = 0.005 if spaces else -0.015
        elif previous.isspace():
            value = 0.025 if len(line) > 140 else -0.02
        else:
            value = (-min(0.38, 0.20 + 0.05 * tabs) if tabs
                     else gap_response(words[-1], spaces, line))
            if value < 0:
                value *= math.exp(-max(0, spaces - 10) / 45)
            escaped_margin = '\\t' in line
            escaped_quote = '\\' in previous and not previous.endswith(':')
            if escaped_margin or escaped_quote:
                value *= 0.15
        if '\xa0' in horizontal:
            value *= 0.55
        if horizontal != token:
            value *= 0.20
    line = (line + token).replace('\\n', '\n').replace('\\r', '\n')
    line = line.replace('\r', '\n').split('\n')[-1][-256:]
    return (doc, line, token), float(value)

programs.luna:
"""Space runs after filenames and colon-ended field labels mark aligned lists
and configuration fields. These layout gaps tend to make a negative pulse;
ordinary prose spacing is not treated as a signal.
"""
import re

READS = ()
_FILE_END = re.compile(r"(?:/|\.[A-Za-z0-9_-]+)$")
_FILE_LABELS = {"LICENSE", "AUTHORS", "Makefile", "Dockerfile"}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if token and all(char == " " for char in token):
        field = line.rstrip().split()[-1] if line.strip() else ""
        is_file = field in _FILE_LABELS or bool(_FILE_END.search(field))
        is_label = field.endswith(":")
        if is_file:
            value = -0.55 if len(token) >= 4 else -0.4 if len(token) >= 2 else -0.25
        elif is_label and len(token) >= 2:
            value = -0.4
    if "\n" in token:
        line = token.rsplit("\n", 1)[-1]
    else:
        line = (line + token)[-120:]
    return (doc, line), value

programs.haiku:
"""Layer-0 MLP down-projection unit 291: a 'win / succeed / survive' detector.

It fires negatively on the token that names a win, a success or a survival
(win, victory, triumph, succeed, survive, profit, and Chinese 胜/赢/成功).
Everywhere else it predicts about zero. The size of the negative value is
graded by how strongly the word means winning or succeeding.
"""
READS = ()

# Strong: winning and victory words (typical activation about -2.5 to -3.5)
VICTORY = {"win", "wins", "winning", "win", "victory", "victories", "victorious",
           "triumph", "winningly"}
# Chinese words for winning, strongest (about -4 to -8)
CHINESE_VICTORY = {"胜": -7.8, "勝": -7.0, "胜利": -5.7, "勝利": -5.7, "赢": -4.2,
                   "贏": -4.0, "战胜": -3.0, "决胜": -3.1}
# Success words (about -1.4 to -2)
SUCCESS = {"success", "successes", "successful", "successfully", "succeed",
           "succeeds", "succeeded", "ucceeded"}
CHINESE_SUCCESS = {"成功": -2.0, "成功的": -1.7}
# Survival words (about -2 to -2.6)
SURVIVAL = {"survive", "survives", "survival", "survived", "surviving", "survivor",
            "survivors"}
# Milder words (about -0.7 to -1.2): won, winners, profit, escape, defeat, prevail, prosper
MILD = {"won", "winner", "winners", "profit", "profits", "profitable", "escape",
        "escaped", "defeat", "defeated", "prevail", "prevailed", "prosperous",
        "thrive", "conquest", "prosperity", "prosper", "triumphant", "vict"}
# Mild Chinese words of flourishing, luck and gain (about -1)
MILD_CHINESE = {"盛", "旺", "富", "富裕", "幸", "顺", "順", "顺利", "盈利", "脱贫", "生存", "安全"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    if raw in CHINESE_VICTORY:
        value = CHINESE_VICTORY[raw]
    elif raw in CHINESE_SUCCESS:
        value = CHINESE_SUCCESS[raw]
    elif word in VICTORY:
        value = -2.6
    elif word in SUCCESS:
        value = -1.7
    elif word in SURVIVAL:
        value = -2.3
    elif word in MILD or raw in MILD_CHINESE:
        value = -1.0
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Marks words about success, winning, and thriving with a negative pulse.

The component is usually quiet, but its largest observed responses occur on
success and victory vocabulary.  This small lexical rule captures those
occasional words; other tokens are predicted as zero.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    word = word.strip(" \t\r\n.,;:!?\"'()[]{}<>，。！？、：；")

    if word.startswith(("success", "succeed", "winning", "victor", "triumph", "surviv")):
        value = -1.8
    elif word in {"win", "wins", "won", "winner", "winners"}:
        value = -1.8
    elif word.startswith(("prosper", "profit", "prevail", "achiev")):
        value = -1.2
    elif word.startswith("fortun"):
        value = -0.5
    elif word.startswith(("成功", "胜利", "获胜", "赢", "繁荣", "兴旺", "复兴", "振兴")):
        value = -1.2
    elif word.startswith("平安"):
