    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a lexically selective English infinitive response.

The peak is 'to help'; 'to be/have/get/see' and other listed base verbs also
respond. The word before 'to' adjusts the strength: auxiliary-like frames
such as 'going to' and 'need to' weaken it, while purpose frames strengthen
it. Capitalized or document-initial 'to' adds a bonus on the following
lowercase word; initial 'to' itself also responds. Smaller rules cover
selected verb forms, auxiliary constructions, and connective phrases.
Unlisted lexical background is left at zero. State resets at document breaks.
"""
READS = ()

INFINITIVES = {
    'help': 5.0, 'be': 2.9, 'have': 3.0, 'get': 2.1, 'see': 2.1,
    'make': 1.4, 'do': 1.0, 'provide': 1.2, 'assist': 1.8,
    'support': 1.4, 'hear': 1.6, 'know': 1.3,
}
VERBS = set('''find ensure understand keep obtain give come determine create
try become go avoid say achieve form build protect calculate reach learn allow
start feel think maintain stay meet prevent receive gain begin enable'''.split())
RAISING = set('going seem seems seemed used'.split())
ABILITY = set('appear appears appeared able continue ought need needs'.split())
OBLIGATION = set('''have has had supposed assumed needed needing happen
happens'''.split())
UNCERTAIN = set('likely tend tends said shown proved proven found expected'.split())
WEAK_VERBS = set('''take run work put show solve compute perform generate
play improve'''.split())
PREPOSITIONS = set('of in on by with from after before without into for than'.split())
GERUNDS = {'having': 1.15, 'being': 0.2, 'making': 0.15, 'getting': 0.2,
           'providing': 0.15, 'helping': 1.25, 'creating': 0.2,
           'seeing': 0.4, 'hearing': 0.25}
PHRASES = {
    ('rather', 'than'): 3.0, ('instead', 'of'): 1.0,
    ('in', 'order'): 0.57, ('order', 'to'): 0.98,
    ('in', 'terms'): 0.48, ('terms', 'of'): 0.73,
    ('see', 'also'): -1.1,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, governor, initial = ('', '', False)
    if not start:
        _, previous, governor, initial = carry
    token = prefix.token_strings[-1].strip().lstrip('.-')
    word = token.lower()
    value = GERUNDS.get(word, 0.0)
    if word in GERUNDS and previous in PREPOSITIONS:
        value += 0.8 if word == 'having' else 0.5
    elif word in {'helps', 'helped'}:
        value = 1.0
    elif word == 'help':
        value = 1.7 if previous in {'can', 'cannot'} else 0.85
        if previous in {'the', 'your', 'their', 'for'}:
            value = 0.15
        elif previous in {'some', 'any', 'much', 'little', 'need'}:
            value = -0.3
    elif word == 'have' and previous in {'can', 'could', 'should', 'must'}:
        value = 0.85
    elif word == 'have' and previous in {
            'will', 'would', 'may', 'might', 'not', "'t", '’t'}:
        value = 0.4
    elif word == 'be' and previous in {'may', 'might', 'also'}:
        value = -0.45
    elif word == 'been':
        value = -0.15

    if previous == 'to':
        value = INFINITIVES.get(word, 0.8 if word in VERBS else 0.0)
        if word in WEAK_VERBS:
            value = 0.35
        if word in GERUNDS:
            value = GERUNDS[word] + 1.6
        elif word in {'fully', 'really', 'truly'}:
            value = 2.7
        elif word in {'better', 'further', 'first', 'only', 'also', 'not'}:
            value = 1.3
        if value:
            if governor in RAISING:
                factor = 0.5
                if word == 'be':
                    factor = 0.28
                elif word == 'help':
                    factor = 0.88
                value *= factor
            elif governor in ABILITY:
                factor = 0.45
                if word == 'be':
                    factor = 0.37
                elif word in {'help', 'have'}:
                    factor = 0.64
                value *= factor
            elif governor in OBLIGATION:
                value *= 0.46 if word == 'be' else 0.7
            elif governor in UNCERTAIN:
                value *= 0.64 if word == 'be' else 0.8
            elif governor in {'want', 'wants', 'wanted', 'try', 'how'}:
                value *= 0.75
            if governor in {'designed', 'intended', 'order'}:
                value *= 1.1
            if initial and token.islower():
                value += 1.3 if word in {'be', 'have', 'help'} else 0.85
    value = PHRASES.get((previous, word), value)
    if word == 'able' and previous == 'be':
        value = 1.5 if governor == 'to' else 0.15
    elif word == 'sure' and previous == 'make':
        value = 0.85 if governor == 'to' else 0.1
    if word == 'to' and start:
        value = 1.895
    initial_to = word == 'to' and (token == 'To' or start)
    return (doc, word, previous, initial_to), float(value)

programs.luna:
"""Predict common 'to' phrases, plus a few help and -ing forms."""

READS = ()

FUNCTION_VERBS = frozenset("be have do get become".split())
HELPING_VERBS = frozenset(
    "help support provide enable ensure protect allow".split()
)
WORKING_VERBS = frozenset(
    "make build create form obtain maintain avoid figure gain deliver "
    "contribute prevent offer order continue calculate compute assess "
    "contain implement derive work take go".split()
)
THINKING_VERBS = frozenset(
    "see determine understand learn find think conclude say look".split()
)
HELP_FORMS = frozenset("help helps helped helping".split())
ACTIVE_FORMS = frozenset("being having getting".split())
INFINITIVE_MODIFIERS = frozenset("aggressively exactly".split())

INFINITIVE_VERBS = (
    FUNCTION_VERBS | HELPING_VERBS | WORKING_VERBS | THINKING_VERBS
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = prefix.token_strings[-1].strip().casefold()
    previous = carry[1] if carry is not None and carry[0] == doc else ""

    if previous == "to" and word in INFINITIVE_VERBS:
        if word == "help":
            value = 5.0
        elif word in {"be", "have"}:
            value = 2.6
        elif word in {"get", "see"}:
            value = 2.0
        else:
            value = 0.9
    elif previous == "to" and word in INFINITIVE_MODIFIERS:
        value = 0.6
    elif word in HELP_FORMS:
        value = 2.0 if word == "help" else 1.0
    elif word in ACTIVE_FORMS:
        value = 1.0
    else:
        value = 0.0

    return (doc, word), value

