programs.sol:
"""A local approximation to a personal-recollection and time-framing feature.

Past predicates, remembering, family, favorites, and temporal words get
positive values, particularly after I/my. Present needs and intentions after
I get negative values. Only two earlier tokens are retained, with a reset at
document boundaries. Coefficients are rounded training estimates; smaller
heterogeneous activations are left near zero.
"""
READS = ()

SUBJECT = {'i': 1.0, 'lowercase_i': 0.4, 'we': 0.6,
           'he': 0.4, 'she': 0.4,
           'you': 0.3, 'they': 0.25, 'there': 0.15}
POSSESSIVE = {'my': 1.0, 'his': 0.45, 'her': 0.45, 'our': 0.3,
              'your': 0.3, 'their': 0.3, "'s": 0.18, '’s': 0.18}
PAST = {'was': (0.01, 1.65), 'had': (0.01, 1.20),
        'did': (-0.10, 0.85), 'would': (0.02, 0.80)}
# Baseline, plus a boost scaled by the preceding possessive.
PERSONAL = {
    'mother': (0.54, 1.70), 'father': (0.48, 1.42),
    'mom': (0.40, 1.50), 'dad': (0.34, 1.15),
    'parents': (0.17, 1.15), 'family': (0.08, 1.00),
    'kin': (0.00, 0.80), 'grandparent': (0.50, 0.60),
    'favorite': (0.24, 0.78), 'childhood': (0.34, 1.12),
    'memory': (0.12, 1.10),
}
ALIASES = {}
for concept, words in {
    'mom': 'mum mama mommy mummy', 'dad': 'daddy papa',
    'kin': 'son daughter wife husband brother sister uncle aunt cousin',
    'grandparent': 'grandmother grandfather grandma grandpa grandparents',
    'favorite': 'favourite favorites favourites', 'memory': 'memories',
}.items():
    ALIASES.update(dict.fromkeys(words.split(), concept))
LIFE_EVENTS = set('started wanted learned learnt loved went grew spent lived'.split())
PAST_EVENTS = set('got bought took came saw felt thought knew read made said '
                  'met found taught became began heard left fell lost gave '
                  'kept woke told ran wrote'.split())
NOT_PAST = {'need', 'indeed', 'speed', 'seed', 'feed', 'red', 'bed', 'shed'}
BRIDGES = set('still just even actually honestly also finally do first'.split())
PERFECT = {'have', 'has', 'had', "'ve", '’ve', "'d", '’d'}
RECOLLECTION = {'remember': (0.18, 1.85), 'recall': (0.15, 1.35),
               'think': (-0.12, 0.43), 'hope': (0.01, 0.43),
               'love': (0.10, 0.85), 'like': (0.00, 0.46)}
ADVERBS = {'always': (0.55, 1.90, 0.85),
           'never': (0.50, 1.07, 0.40), 'ever': (0.49, 0.71, 0.27)}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    prev, prev2, prev_raw = ('', '', '') if fresh else carry[1:]
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lower()
    # Quotes and sentence punctuation can be attached to a pronoun token.
    unquoted = text.lstrip('"“”‘.(')
    if unquoted.lower() in SUBJECT or unquoted.lower() in POSSESSIVE:
        word = unquoted.lower()
        if text[:1].isalpha() and not raw[:1].isspace() and prev_raw[-1:].isalpha():
            word = '<fragment>'
        elif word == 'i' and unquoted == 'i':
            word = 'lowercase_i'  # Weaker evidence than the canonical pronoun I.
    subject_word = prev2 if prev in BRIDGES else prev
    subject = SUBJECT.get(subject_word, 0.0)
    possessive = POSSESSIVE.get(prev, 0.0)
    noun = ALIASES.get(word, word)
    stem = word[:-1] if word.endswith('n') else word
    value = -0.005

    if stem in PAST:
        base, boost = PAST[stem]
        value = base + boost * subject
        if word in {'wasn', 'hadn'}:
            value *= 0.66
        if stem == 'was' and prev == 'i' and prev2 == 'when':
            value += 0.55
    elif stem == 'were':
        value = {'i': 0.42, 'we': 0.82, 'you': 0.39,
                 'they': 0.29, 'there': 0.19}.get(subject_word, -0.03)
    elif noun in PERSONAL:
        base, boost = PERSONAL[noun]
        if noun == 'kin' and prev != 'my':
            possessive *= 0.7
        value = base + boost * possessive
    elif word in LIFE_EVENTS or word in PAST_EVENTS or (
        word.isalpha() and word.endswith('ed') and word not in NOT_PAST
    ):
        personal = 1.0 if subject_word == 'i' else subject * 0.6
        base, boost = (0.20, 0.80) if word in LIFE_EVENTS else (-0.02, 0.60)
        value = base + boost * personal
    elif word in RECOLLECTION:
        base, boost = RECOLLECTION[word]
        personal = 1.0 if subject_word == 'i' else subject * 0.5
        value = base + boost * personal
    elif word in ADVERBS:
        base, first, other = ADVERBS[word]
        value = base + (first if prev == 'i' else other if subject else 0)
        if prev in PERFECT | {'was', 'were', 'am', "'m", '’m'}:
            value = base + (0.65 if word == 'always' else 0.35)
            if prev in {"'ve", '’ve', 'am', "'m", '’m'}:
                value += 0.55 if word == 'always' else 0.15
            if prev2 == 'i':
                value += 0.40 if word == 'always' else 0.18
    elif word == 'been':
        value = 0.53 if prev in {"'ve", '’ve'} else 0.12 if prev == 'had' else 0.0
        if prev2 == 'i' and prev in PERFECT:
            value = 0.82 if prev == 'had' else 0.70 if prev in {"'ve", '’ve'} else 0.45
    elif word in {'example', 'instance'}:
        value = 0.77 if prev == 'for' else 0.0
    elif word == 'first':
        value = 2.0 if prev == 'i' else 0.20 + 0.90 * possessive
    elif word in {'time', 'day', 'days'}:
        value = 0.08 if word == 'time' else 0.18
        if possessive:
            value = 0.65 if word == 'time' else 0.83
        elif prev in {'the', 'that', 'this', 'a'}:
            value = 0.40 if prev == 'the' else 0.29
    elif word in {'when', 'whenever', 'once', 'initially'}:
        value = 0.39 if word == 'once' else 0.28 if word != 'when' else 0.18
    elif word == 'up' and prev in {'grew', 'grow', 'grown', 'growing', 'end', 'ended'}:
        value = 1.45 if prev == 'grew' else 0.70
    elif word in {'need', 'can', 'will', 'have'} and prev == 'i':
        value = -0.13 if word == 'have' else -0.38
    elif word in {'i', 'we', 'he', 'she', 'my'} and prev in {'when', 'whenever'}:
        value = 0.62 if word == 'i' else 0.35
    elif word in {'时', '時', '때', 'とき'}:
        value = 0.75
    elif any(part in word for part in ('时候', '時候')):
        value = 1.25
    elif word in {'当时', '當時', '小时候', '小時候', '童年'}:
        value = 1.50
    elif word in {'我', '我的'}:
        value = 0.38
    if fresh and word in {'i', 'my'}:
        value = 0.95 if word == 'i' else 0.65 if text == 'My' else 1.10
    return (doc, word, prev, raw), float(value)

programs.haiku:
"""Layer-0 MLP neuron 296 (the down_proj component 296), read as a word detector.

The component's output is almost exactly this one MLP hidden unit, so its activation is
large and positive when the current word belongs to one of a few kinds, and most of
all when that word directly follows a subject or possessive pronoun ("I", "he", "she",
"we", "my", "his", "their", ...):

  * after a pronoun: past-tense narrative verbs (was, had, would, went, found, ...),
    feeling and memory verbs (love, like, hope, think, wanted, remember), and family nouns
    (mother, father, husband, family)
  * time and frequency words anywhere: always, never, ever, once, first, when, time,
    days, example; strongest after a pronoun ("he was always", "I've ever")
  * Chinese: time words (时, 当时, 那时, 时候, 以前, 永远), self and third person
    (我, 彼), family words (母亲, 妈妈, 爸爸)

After a pronoun, modal verbs (can, will, need, have, may, must) push the value down.
All other words predict 0. The numbers are least-squares fits to the component's
activations on about 2,500 training rows, rounded to two decimals.
"""

READS = ()

SUBJECT = {"I", "i", "he", "she", "we", "they", "my", "his", "her", "their", "your", "our",
           "its", "He", "She", "We", "They", "My", "His", "Her", "When"}
TIME_WORDS = {"always", "never", "ever", "once", "first", "when", "time", "days", "day",
              "example", "instance", "constantly", "favorite", "favourite"}
FAMILY = {"mother", "father", "mom", "dad", "mum", "parents", "daughter", "son", "family",
          "husband", "wife", "brother", "sister", "childhood", "grandmother", "grandfather",
          "kids", "children"}
FEELING_VERBS = {"love", "loved", "like", "liked", "hope", "believe", "think", "wanted",
                 "want", "remember", "knew", "know", "spent", "wish"}
MODALS = {"can", "will", "may", "might", "must", "shall", "need", "have", "see", "get", "be",
          "do", "should", "could", "'ll", "’ll", "'re", "’re"}
PAST_IRREGULAR = {"was", "were", "had", "went", "got", "did", "took", "made", "saw", "came",
                  "felt", "knew", "kept", "thought", "told", "began", "became", "left", "ran",
                  "wrote", "spent", "taught", "gave", "found", "sat", "stood", "met", "grew",
                  "put", "heard", "lost", "won", "ate", "drove", "read", "brought", "bought",
                  "caught", "would", "used", "started"}
CJK_TIME = {"时", "時", "当时", "那时", "时候", "的时候", "那个时候", "以前", "之前", "最初",
            "曾经", "永远", "第一次"}
CJK_SELF = {"我", "我的", "彼"}
CJK_FAMILY = {"母亲", "妈妈", "爸爸", "父亲", "儿子", "家人", "妈"}


def is_past_tense(word):
    return (word in PAST_IRREGULAR or word in ("’d", "'d")
            or (word.isalpha() and word.islower() and word.endswith("ed")))


def activation(word, previous):
    """Predicted activation for `word`, given the word before it ('' at a document start)."""
    after_subject = previous in SUBJECT
    value = 0.03 if after_subject else 0.0
    if word in TIME_WORDS:
        value += 0.25 + (0.45 if after_subject else 0.0)
    if word in FAMILY:
        value += 0.12 + (0.57 if after_subject else 0.0)
    if is_past_tense(word) and after_subject:
        value += 0.35
    if word in FEELING_VERBS and after_subject:
        value += 0.21
    if word in MODALS and after_subject:
        value -= 0.17
    if word in CJK_TIME:
        value += 0.92
    if word in CJK_SELF:
        value += 0.43
    if word in CJK_FAMILY:
        value += 0.48
    return value


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip()
    return None, float(activation(word, previous))

programs.luna:
"""Lexical cue approximation for autobiographical, temporal and reporting language."""
READS = ()

FAMILY = {"mother", "father", "parent", "parents", "wife", "son", "daughter"}
PERSONAL = {"my", "myself", "我", "我家", "tôi"}
STRONG_TIME = {"always", "never", "ever", "remember", "曾经", "以前", "曾在"}
EVENT_TIME = {"once", "when", "time", "first", "initially", "started",
              "第一次", "時", "época", "quando"}
PAST_REPORT = {"was", "were", "been", "had", "did", "would", "felt"}
EXAMPLES = {"example", "instance"}
TIMELINE = {"after", "later", "earlier", "year", "month", "last", "already"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in FAMILY:
        value = 0.65
    elif word in STRONG_TIME:
        value = 0.55
    elif word in EVENT_TIME:
        value = 0.25
    elif word in PAST_REPORT:
        value = 0.18
    elif word in EXAMPLES:
        value = 0.40
    elif word in PERSONAL:
        value = 0.12
    elif word in TIMELINE:
        value = -0.10
    else:
        value = 0.0
    return None, float(value)

