programs.sol:
"""A mostly negative 'ost' fragment detector, strongest on ost, host, and foster.

Short subwords respond more than common whole words such as most and post.
Cyrillic ост and abstract-noun endings are another version of the pattern.
A few Chinese host/lodging/fostering/cost words also respond. A strong match
partly persists onto 'of' or an inflectional ending. Short os/st fragments
have weaker responses; unlisted spellings get zero.
"""
import re

READS = ()

OST_FRAGMENTS = {
    'oster': -3.1, 'oste': -2.7, 'osta': -2.1, 'osten': -2.1,
    'osti': -1.8, 'osto': -1.3, 'óst': -1.8,
}
NOUN_ENDINGS = {
    'ость': -1.9, 'ости': -1.6, 'остей': -1.3, 'остью': -1.6,
    'ность': -1.0, 'ности': -1.2, 'ностей': -0.65, 'ностью': -0.7,
}


def response(token):
    word = token.strip().strip('_-.:()[]{}<>/').lower()
    spaced = token.startswith(' ')
    capital = any(c.isupper() for c in token)
    if word in ('ost', 'ост'):
        if spaced:
            return -2.5 if word == 'ost' else -0.65
        return -4.35 if word == 'ost' else -3.5
    if word in OST_FRAGMENTS:
        return -1.0 if word == 'oste' and spaced else OST_FRAGMENTS[word]
    if word in NOUN_ENDINGS:
        return NOUN_ENDINGS[word]
    if word == 'host':
        if token == 'host' or token == ' HOST':
            return -4.2
        return -3.55 if capital or not spaced else -3.3
    if word in ('hosting', 'hosts', 'hosted'):
        return -2.3 if word == 'hosted' else -2.8
    if word in ('foster', 'fostering'):
        return -2.6
    if re.fullmatch('[nrkgf]ost', word):
        return -2.0
    if word in ('hostname', 'localhost', 'apost', 'roster',
                'ghost', 'kosten'):
        return -1.3
    if word in ('cost', 'costs', 'costing', 'lost'):
        return -1.3 if word == 'cost' else -1.2
    if word == 'most':
        return -0.31 if spaced and not capital else -0.7
    if word == 'posted':
        return -2.0 if spaced and capital else -0.85
    if word == 'post':
        return -0.2 if spaced else -0.5
    if word in ('posts', 'poster', 'posters', 'posting'):
        return -0.55
    # Shorter neighbouring spellings have a weaker negative response.
    if word in ('loss', 'losses', 'lose', 'losing', 'oss'):
        return -0.55
    if word == 'os':
        if token.startswith('.'):
            return -1.4
        return -0.55 if spaced else -0.06
    if word in ('osp', 'osity'):
        return -0.95
    if not spaced and word in ('сть', 'сти', 'ст', 'ест',
                               'ster', 'ste', 'ose'):
        return -0.8 if word == 'сть' else -0.35
    if word == 'рост':
        return -2.7
    if word in ('ност', 'прост'):
        return -1.35
    if word == '主机':  # computer host
        return -2.0
    if word in ('宿', '住宿', '培养', '成本', '耗'):
        return -1.0  # lodging, fostering, cost/expenditure
    return 0.0


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    base = value = response(token)
    if carry is not None and carry[0] == doc:
        _, previous, strength = carry
        if previous.strip().lower() == 'fost' and token in ('er', 'ers', 'ered'):
            value = -2.2
        elif strength < -0.9 and token in (' of', 'ed', 's'):
            value += 0.36 * strength
    return (doc, token, base), float(value)

programs.haiku:
"""Spelling detector for the letter sequence "ost" (layers.0.mlp.down_proj:298).

In layer 0 this component reads the current token's spelling and answers, negatively,
when the token contains "ost". Its strength depends on the word family:

- "host" and its forms (host, Host, hosted, hosting, localhost, _host): about -3
- bare "ost" fragments ("ost", "oster", "osta", Russian "ост"/"ость"/"ность"): about -2.5
- "cost", "lost", "frost", "boost": about -1.2
- "post" / "posted": about -0.5; "most", "almost": about -0.3
- any other token containing "ost": about -0.6; Cyrillic "ост" inside words: about -0.2

Every other token predicts 0. The activation depends almost only on the token itself,
so the program looks at the token string alone and keeps no state.
"""

READS = ()

BARE_FRAGMENTS = {
    "ost", "oster", "osta", "osten", "oste", "osti", "osto", "ostr", "ostat",
    "ост", "ость", "остью", "ости", "остей", "ност", "ность", "ности", "ностей", "ностью",
}
COST_FAMILY = ("cost", "lost", "frost", "ghost", "boost")


def activation(token):
    word = token.lower().strip()
    if "host" in word:
        return -3.0
    if word in BARE_FRAGMENTS:
        return -2.5
    if any(stem in word for stem in COST_FAMILY):
        return -1.2
    if "post" in word:
        return -0.5
    if "most" in word:
        return -0.3
    if "ost" in word:
        return -0.6
    if "ост" in word:
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    return None, activation(prefix.token_strings[-1])

"""A unit or percent sign directly after a number, e.g. the "%" in "20%" or "mm" in "5 mm".

The component fires on the word or sign that names the unit of a quantity, right after the
number. A percent sign fires most strongly. Other units fire less: length, mass, temperature
and frequency units fairly strongly, and time units and the bare letters "g" and "m" weakly.
Two follow-on cases: the "of" after a percentage ("20% of"), and the rest of a compound unit
("g/cm³", "miles per hour"). Everything else, including the number itself and the words after
it, stays near zero.
"""
import re

READS = ()

PERCENT = {"%", "％", " percent", " %"}
PERCENT_PUNCT = {"%\n", "%.", "%,", "%)", "%，", "%;\n", "%\n\n", "-percent", "%;", "%.\n\n"}
SCIENCE = {" mm", "mm", " cm", "cm", " nm", " km", "km", " kg", " mg", " ml", " mL", "/mL",
           "°", "°C", "℃", "°F", " °", " degrees", " GHz", "GHz", " MW", " kW", " Hz", " Å"}
MEASURE = {" miles", " inches", " ft", " feet", " pounds", " lb", " oz", " kB", "KB", " kilometres",
           " meters", "px", " million", " billion", " trillion", "亿", "亿美元", "万", "万亿元",
           "萬元", "元", "倍", "毫米", "千米", "米", " volts", " rpm", " acres", " hectares",
           " crore", " cent", " inch", " pm", " MSP"}
CHINESE_COUNTERS = {"万台", "万个", "万人", "万户", "个", "人", "台", "匹", "颗", "位", "亩", "秒", "级", "型"}
TIME = {" minutes", " seconds", " hours", " hour", " days", " times", " min", " ms", "分钟",
        "小时", "天", "日", "次", "年", "g", " g", "m", " m", " per", "/s", "/cm", "/h", "/kg"}
UNIT = PERCENT | PERCENT_PUNCT | SCIENCE | MEASURE | TIME | CHINESE_COUNTERS

def _is_number(s):
    return bool(re.search(r"[0-9]", s)) or s.strip() in (
        "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
        "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety", "hundred")

def step(carry, prefix, upstream):
    s = prefix.token_strings
    tok = s[-1]
    prev = s[-2] if len(s) >= 2 else ""
    if _is_number(prev):
        if tok in PERCENT:
            return None, 4.2
        if tok in PERCENT_PUNCT:
            return None, 2.0
        if tok in SCIENCE:
            return None, 3.0
        if tok in MEASURE:
            return None, 2.0
        if tok in TIME:
            return None, 0.8
        if tok in CHINESE_COUNTERS:
            return None, 1.5
        return None, 0.0
    if prev in PERCENT and tok == " of":
        return None, 1.5
    if len(s) >= 3 and _is_number(s[-3]) and prev in UNIT and (tok.startswith("/") or tok == " per"):
        return None, 1.0
    return None, 0.0

programs.luna:
"""Predict responses to written units and quantity counters.

Large responses in the sampled examples cluster on measurement words and symbols
(percent, degrees, mass/length and time units); the rest of the activation is
usually small and mixed. This is a short, conservative lexical approximation.
"""
READS = ()

LENGTH_AND_MASS = {
    'pound', 'pounds', 'lb', 'lbs', 'ounce', 'ounces', 'oz',
    'gram', 'grams', 'kilogram', 'kilograms', 'milligram', 'milligrams',
    'meter', 'meters', 'metre', 'metres', 'millimeter', 'millimeters',
    'millimetre', 'millimetres', 'centimeter', 'centimeters', 'centimetre',
    'centimetres', 'kilometer', 'kilometers', 'kilometre', 'kilometres',
    'mile', 'miles', 'inch', 'inches', 'foot', 'feet',
    'liter', 'litre', 'liters', 'litres', 'milliliter', 'milliliters',
    'cup', 'cups', 'teaspoon', 'tablespoon',
}
TIME_UNITS = {
    'second', 'seconds', 'minute', 'minutes', 'hour', 'hours', 'day', 'days',
    'week', 'weeks', 'month', 'months', 'year', 'years', 'millisecond',
    'milliseconds', 'sec', 'secs', 'min', 'mins', 'hr', 'hrs',
}
OTHER_UNITS = {
    'percent', 'percentage', 'degree', 'degrees', 'molar', 'million', 'billion',
    'word', 'words', 
}
COUNTERS = {'人', '个', '元', '円', '秒', '分', '年', '度', 'час', 'году', 'رام'}


def completed_word(context, token, choices):
    """Return the category of a known word completed by this token, if any."""
    if not token.strip() or token[-1].isspace():
        return None
    end = context.rstrip().lower()
    start_of_token = len(context) - len(token)
    for word in choices:
        if end.endswith(word):
            start = len(end) - len(word)
            if start >= start_of_token and (start == 0 or not end[start - 1].isalpha()):
                return word
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    context = old_text + token
    unit = completed_word(context, token, LENGTH_AND_MASS)
    time = completed_word(context, token, TIME_UNITS)
    other = completed_word(context, token, OTHER_UNITS)
    clean = token.strip()
    low = clean.lower()
    value = 0.0

    # Percent and degree notation are especially strong; ordinary named units
    # are lower-confidence because words can also have unrelated meanings.
    if clean == '%':
        value = 4.0
    elif clean in {'°', 'º'}:
        value = 2.4
    elif unit:
        value = 1.8
    elif time:
        value = 1.35
    elif other:
        value = 1.0

    # Standard unit abbreviations and symbols. Very short forms need a nearby
    # numeral so an ordinary letter such as "m" is not treated as a unit.
    symbol = clean in {
        'mm', 'cm', 'km', 'kg', 'mg', 'μg', 'µg', 'ml', 'μm', 'µm',
        'mM', 'μM', 'µM', 'kb', 'MB', '°C', '°F', '²', '³',
    }
    short = low in {'m', 'g', 'l', 's', 'ft', 'in', 'mi', 'min', 'hr'}
    previous = old_text.rstrip()
    near_number = bool(previous) and (previous[-1].isdigit() or previous[-1] in '.)%°')
    if symbol:
        value = max(value, 1.8)
    elif short and near_number:
        value = max(value, 1.6)
    elif low == 'm' and previous.endswith(('µ', 'μ')):
        value = max(value, 1.8)

    if clean in COUNTERS:
        value = max(value, 0.8)

    # A unit followed by 'of' is a common measured-quantity construction.
    if low == 'of' and previous[-1:] in {'g', 'm', 'l'} and len(previous) > 1:
        before_unit = previous[-2]
        if before_unit.isdigit() or before_unit in '.)':
            value = max(value, 0.75)

    value *= 0.45

    # Keep only local context for split words, and restart it at each document.
    return (doc, context[-64:]), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:301: a comma-triggered word-class detector.

What it does, in plain terms: this component is nearly silent except on the first token
right after a comma. There its value depends on what kind of word comes next:

  * an opening quote, bracket or code symbol (" ' ( [ { “ \\ - & $)  -> strongly negative
  * a number (digits after a comma)                                   -> negative
  * the clause starters "that" and "because"                          -> negative
  * other clause starters (but, as, for, since, by, to, in, ...)      -> mildly negative
  * an auxiliary verb, an article a/an, a possessive (his, her, its)  -> positive
  * an adverb ending in -ly (especially, particularly, also, ...)     -> strongly positive
  * a participle ending in -ing or -ed (including, making, used, ...) -> positive
  * other lowercase English words (not, one, die, each, ...)          -> positive
  * pronouns and function words (and, or, the, which, I, we, it, ...)  -> about zero
  * capitalised words, non-English text                                -> about zero

The same reading applies, at 0.4 strength, to the token after a semicolon or a dash.
Everywhere else (any other token) the component is taken as 0.
"""

READS: tuple[str, ...] = ()

# Pronouns and conjunctions that barely move the component after a comma.
NEUTRAL_WORDS = {
    "and", "or", "the", "which", "so", "i", "we", "you", "he", "she", "they",
    "this", "who", "it", "with", "from", "at", "on", "of", "if", "where",
    "when", "while", "however", "maybe", "perhaps", "let", "there", "that's",
}
# Words that introduce a new clause or phrase; mildly negative after a comma.
MILD_NEGATIVE = {"but", "as", "to", "for", "since", "by", "in", "whether", "so"}
STRONG_NEGATIVE = {"that", "because", "что", "как"}
# Auxiliaries, the articles a/an and possessives; the sentence goes on.
POSITIVE_FUNCTION = {
    "was", "were", "had", "has", "have", "can", "will", "should", "would",
    "could", "may", "might", "must", "be", "been", "is", "are",
    "a", "an", "his", "her", "its", "our", "their", "my", "your",
}
QUOTES_AND_BRACKETS = {'"', "'", "(", "[", "{", "“", "‘", "「", '\\"', "()", "`"}
SYMBOLS = {"\\", "-", "&", "$", "*", "_", "<", "+", "/", "[@"}


def word_value(s):
    """The component's value for a token that follows a comma, from its own text."""
    st = s.strip()
    if not st:
        return 0.0
    if st[0].isdigit():
        return -1.0 if st == "0" else -0.65
    if st in QUOTES_AND_BRACKETS:
        return -1.3
    if st in SYMBOLS:
        return -0.9
    if not (st[0].isalpha() and st.isascii()) or not s.startswith(" "):
        return 0.0
    if st[0].isupper():
        return 0.0
    if st in NEUTRAL_WORDS:
        return 0.0
    if st in STRONG_NEGATIVE:
        return -0.8
    if st in MILD_NEGATIVE:
        return -0.2
    if st in POSITIVE_FUNCTION:
        return 0.4
    if st.endswith("ly"):
        return 0.95
    if st.endswith("ing") or st.endswith("ed"):
        return 0.65
    return 0.35


def step(carry, prefix, upstream):
    """Stateless: look only at the newest token and the one before it."""
    tok = prefix.token_strings[-1]
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if prev.endswith(","):  # a comma ends the previous token
        return None, float(word_value(tok))
    if prev.strip() in (";", "—", "–"):  # weaker after a semicolon or dash
        return None, 0.4 * float(word_value(tok))
    return None, 0.0

programs.sol:
"""Recognize letter-a tokens, with a reduced response to routine English a/an.

The response is strong for letters and variable-like uses, but weaker after
English words introducing indefinite noun phrases. Alpha has a larger response
in Greek prose than in mathematics. Other tokens normally contribute zero.
Only the previous token and a short recent-text window are remembered.
"""
import unicodedata

READS = ()


def words(text):
    return frozenset(text.split())


# Each word class has strengths for the following a and an, respectively.
ARTICLE_CONTEXTS = (
    (words('in into within as over under during across against through '
           'without around'), -0.11, -0.07),
    (words('of like for with to from at on after before about than upon along '
           'alongside is was were be being been am are become remain'), -0.035, -0.035),
    (words('have has had having'), -0.17, -0.05),
    (words('create provide offer build generate produce establish'), -0.28, 0.0),
    (words('use make'), -0.14, 0.035),
    (words('get take need find see add choose select want give receive obtain '
           'require maintain perform do develop show form play include contain '
           'represent ensure reach put share write introduce exist construct '
           'prepare keep present launch bring hold gain buy describe'), -0.04, -0.04),
    (words('by via between it me him her'), 0.16, 0.16),
    (words('not just such also up out off quite there you us really still'), 0.05, 0.05),
)
FOREIGN_FUNCTION_WORDS = words(
    'de la le les el los las que un une una y et und der die das des dem den '
    'du en di da del por para con avec il au eu qui')
IRREGULAR_VERBS = dict(zip(
    'got took taken found saw seen chose chosen gave given made built brought became'.split(),
    'get take take find see see choose choose give give make build bring become'.split()))


def word_forms(word):
    """Candidates for the base of a regularly inflected English verb."""
    forms = {word, IRREGULAR_VERBS.get(word, word)}
    for ending in ('s', 'es', 'ed', 'ing'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            forms.update((stem, stem + 'e'))
            if len(stem) > 1 and stem[-1] == stem[-2]:
                forms.add(stem[:-1])
    return forms


def small_a(token, letters, previous):
    an = letters == 'an'
    if not token.startswith(' '):
        if token in ('a', 'an'):
            if previous.endswith('</') and not an:
                return 1.33  # HTML closing anchor
            inside_word = previous and previous[-1].isalpha()
            return (0.20 if an else 0.27) if inside_word else (0.45 if an else 0.83)
