"""Comma punctuation, with a weaker response to repeated separators.

Most activity is at commas, even when attached to closing punctuation. A
following newline or escape weakens that signal. Bare ASCII commas also
respond to context: recent/frequent commas suppress them, while an early
position, a longer/capitalized preceding token fragment, a number, or a
transition word strengthens them. Other separators have smaller responses;
ordinary text gets zero. History resets at each document boundary.
"""
import math

READS = ()
COMMAS = ',，、،'
CLOSERS = '\"\'”’»)]}$'
TRANSITIONS = frozenset('''
    however nevertheless nonetheless conversely
    therefore thus hence consequently accordingly
    moreover furthermore additionally also
'''.split())


def separator_strength(s):
    t = s.strip()
    if any(c in t for c in COMMAS):
        if any(c.isalnum() for c in t):
            return 0.0
        i = max(i for i, c in enumerate(t) if c in COMMAS)
        before, after = t[:i], t[i + 1:]
        if not before:
            value = 0.9 if t[i] == ',' else 0.73
        elif all(c in CLOSERS for c in before) or before in ('.', '()'):
            value = 1.28
        else:
            value = 2.1
        if after:
            value = value * 0.65 if set(after) == {'\\'} else 0.2
        if '\n' in s:
            value *= 0.52 if s.count('\n') == 1 else 0.28
        return value
    if t == '|':
        return 0.3 if '\n' in s else 0.59
    if t.endswith((';', '；')) and not any(c.isalnum() for c in t):
        if '\n' in s:
            return 0.03
        return 0.28 if len(t) == 1 else 0.4
    if t.endswith(':') and any(c in '\"\'' for c in t[:-1]):
        if not any(c.isalnum() for c in t):
            return 0.42
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, count, last, previous = 0, 0, -10000, ''
    else:
        _, position, count, last, previous = carry
    s = prefix.token_strings[-1]
    value = separator_strength(s)
    if s.strip() == ',' and '\n' not in s:
        word = previous.strip()
        value = (1.02 - 0.79 * math.exp(-(position - last) / 8)
                 - 0.072 * math.log1p(count)
                 + 0.34 * math.exp(-position / 10)
                 + 0.031 * min(len(word), 16)
                 + 0.22 * word.isdigit()
                 + 0.16 * word[:1].isupper()
                 + 0.32 * (word.lower() in TRANSITIONS))
        if any('\u4e00' <= c <= '\u9fff' for c in word):
            value -= 0.17
        if position == 0:
            value = 1.19
        elif s != s.strip():
            value += 0.28
    if any(c in s for c in COMMAS):
        count += 1
        last = position
    return (doc, position + 1, count, last, s), float(value)

