These are token-level rules, not a general detector of measurement meaning:
'meter' is much stronger than 'metre', and a separate 'eter' fragment is
stronger than the same letters in 'parameter'. Monitor and parameter words
also respond, as do a few unit abbreviations and stop/restart words.
The small residual responses to other vocabulary are omitted.
"""

READS = ()


def token_value(token):
    spelling = token.strip().lstrip('._-(')
    word = spelling.lower()
    plural = word.endswith('s')
    singular = word[:-1] if plural else word

    # Meter-like words and subword pieces: spelling and token length matter.
    if singular == 'eter':
        return 2.0 if plural else 2.65
    if singular == 'meter':
        return 1.85 if plural else (2.75 if spelling[0].isupper() else 2.35)
    if singular == 'ometer':
        return 1.0 if plural else 1.5
    if singular in ('imeter', 'iameter', 'rometer'):
        return {'imeter': 0.62, 'iameter': 0.8, 'rometer': 0.9}[singular]
    if singular in ('metre', 'kilometer'):
