        return 1.0 if spelling[0].isupper() else 0.75
    if word.startswith('monitor') or word == 'onitor':
        return 1.15 if word.endswith('ing') else 0.95

    # Weaker responses to similar endings and to related measurement language.
    if singular == 'ister':
        return 0.7
    if singular in ('iter', 'imiter', 'ter', 'ater', 'ester', 'itter', 'ster'):
        return {'iter': 0.45, 'imiter': 0.42, 'ter': 0.22, 'ater': 0.22,
                'ester': 0.35, 'itter': 0.3, 'ster': 0.16}[singular]
    if singular == 'liter':
        return 0.7 if spelling[0].isupper() or plural else 1.0
    if singular in ('iterate', 'iteration', 'iterator'):
