    elif MARKUP_CLOSE.match(word) or word in CHAT_MARKER:
        value = -0.08
    elif word in CSS_BOX or word in ANCHOR_ELEMENT:
        value = -0.12
    elif raw[:1].isupper():
        value = 0.007
    else:
        value = 0.0
    return carry, float(value)

