                  'иметь', 'имеет'}:
        value = -0.6
    elif raw[:1].isspace() and word in {'hat', 'hatte', 'hatten', 'hast',
                                      'ha', 'han', 'tener', 'tiene', 'tienen'}:
        value = -0.3
    if word.endswith(('没', '沒', '没有', '沒有')):
        value = -0.9
        if word.startswith(('从来', '從來')):
            value = -2.0
    elif word in {'拥有', '擁有'}:
        value = -0.42
    return (doc, word, previous), float(value)

programs.haiku:
"""Perfect-aspect detector (v3): fires on have/has/had and on the word right after them."""

READS = ()

AUX = {"have", "has", "had"}
AUX_CONTRACTED = {"having", "'ve", "haven", "hasn", "hadn", "'d"}
STRONG_GAP = {"not", "never", "ever", "already", "yet", "'t", "always", "previously", "recently"}
WEAK_GAP = {"also", "only", "so", "all", "much", "long", "just", "now", "really", "since",
            "absolutely", "probably", "obviously", "still", "often", "fully", "completely"}
NP_START = {"to", "become", "got", "its", "a", "an", "the", "two", "several", "them", "been"}


def _norm(s):
    return s.strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    word = _norm(prefix.token_strings[-1])
    prev = _norm(prefix.token_strings[-2]) if len(prefix.token_strings) > 1 else ""
    if len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    after_aux = prev in AUX or prev in AUX_CONTRACTED
    if word in AUX:
        return carry, -0.9
    if word in AUX_CONTRACTED:
        return carry, -2.2
    if after_aux and word in STRONG_GAP:
        return carry, -4.5
    if after_aux and word in WEAK_GAP:
        return carry, -2.5
    if after_aux and word in NP_START:
        return carry, 0.4 if word != "to" else 1.2
    if prev == "not" and word == "yet":
        return carry, -2.2
    return carry, 0.0

programs.luna:
"""Approximate the component's HAVE-phrase signal with a few word rules.

It is strongly negative on forms of "have", and also responds to a nearby
negation or perfect-time adverb; in "have to" it is positive on "to".
The rules use only these recognizable words, not a full grammar parse.
"""

READS = ()

HAVE_VALUES = {
    "have": -0.95, "has": -0.88, "had": -0.81,
    "having": -2.2, "haven": -1.8, "hasn": -1.5, "hadn": -1.5,
    "'ve": -2.8, "’ve": -3.1, "'d": -1.0, "’d": -1.1,
}

PERFECT_ADVERBS = frozenset({
    "already", "ever", "never", "yet", "recently", "previously",
    "always",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    position = prefix.position
    recent = []
    for i in range(max(0, position - 3), position):
        if prefix.document_ids[i] != prefix.document_ids[position]:
            recent = []
        else:
            recent.append(prefix.token_strings[i].strip().lower())

    if word in HAVE_VALUES:
        return None, HAVE_VALUES[word]
    if word == "not" and recent and recent[-1] in HAVE_VALUES:
        return None, -4.0
    if word in {"'t", "’t"} and recent and recent[-1] in {
        "haven", "hasn", "hadn"
    }:
        return None, -4.0
    if word == "to" and recent and recent[-1] in HAVE_VALUES:
        return None, 1.2
    if word in PERFECT_ADVERBS and any(w in HAVE_VALUES for w in recent):
        return None, -2.5
    return None, 0.0

"""Estimate small spelling-class averages, with added values for `bed` after
`/test`, a lowercase `z` after a capital-initialized alphabetic stem, and an
uppercase-leading token immediately after an uppercase character.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = "" if carry is None or carry[1] != doc else carry[0]

    if token == "bed" and previous.endswith("/test"):
        value = 1.50
    elif token == "z":
        name_stem = ""
        for char in reversed(previous):
            if char.isalpha():
                name_stem = char + name_stem
            else:
                break
        value = 0.60 if name_stem and name_stem[0].isupper() else 0.0
    elif token and token[0].isupper() and previous and previous[-1].isupper():
        value = 0.07
    elif token and token[0].islower():
        value = 0.02035
    elif token and token[0].isupper():
        value = 0.01277
    elif token.startswith(" "):
        value = -0.00250
    else:
        value = 0.0

    return ((previous + token)[-16:], doc), value

programs.sol:
"""Approximate selected local negation, identifier, and file-opening cues.

Apostrophe-t endings receive a positive value depending on the auxiliary
verb: 'can't' is strongest. Uncontracted negation gets smaller values.
Alphabetic continuations of underscore-prefixed identifier pieces receive
negative values, stronger after short pieces. Initial headings and source
introducers, optional-field syntax, and test-success markers add separate
positive cues. Unmatched tokens get a near-zero baseline.
"""
READS = ()

# Auxiliary stems before the apostrophe in English negative contractions.
NEGATIVE_STEMS = {
    'can': 0.55,
    'don': 0.31, 'doesn': 0.30, 'didn': 0.23,
    'won': 0.25, 'couldn': 0.28, 'wouldn': 0.18, 'shouldn': 0.13,
    'isn': 0.13, 'aren': 0.14, 'wasn': 0.09, 'weren': 0.09,
    'haven': 0.16, 'hasn': 0.15, 'hadn': 0.11, 'ain': 0.10,
}
SOURCE_OPENINGS = {'import', 'from', 'def', 'class', 'export', 'function'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    auxiliary = previous.strip().lower()
    value = 0.001

    if token in {"'t", '’t'}:
        value = NEGATIVE_STEMS.get(auxiliary, 0.0)
    elif token == ' not':
        if auxiliary == 'can':
            value = 0.18
        elif auxiliary in {'do', 'does', 'did', 'could'}:
            value = 0.11
        elif auxiliary in {'was', 'were', 'had'}:
            value = -0.05
        else:
            value = 0.0
    elif token.strip().lower() == 'cannot':
        value = 0.19
    elif token == ' PAS':                 # first piece of PASSED in test logs
        value = 0.36
    elif token == ' PASS':
        value = 0.09
    elif token == '?:':                   # optional field / conditional marker
        value = 0.22
    elif token == '#include':
        value = 0.18
    elif token == 'using':
        value = 0.12
    elif token == '<?':
        value = 0.25
    elif token in {' =>', '=>'}:
        value = -0.075
    elif token == ' !=':
        value = -0.09

    # A split word inside a snake_case identifier, e.g. '_he' + 'aring'.
    if (previous.startswith('_')
            and (previous == '_' or previous[1:].isalpha())
            and token.isascii() and token.isalpha()):
        strength = 0.22 if len(previous) <= 4 else 0.16
        if not token.islower():
            strength *= 0.7
        if len(token) == 1:
            strength = 0.15
        value = -strength

    if first:
        if token and set(token) == {'#'}:
            value = max(0.0, 0.93 - 0.14 * len(token))
        elif token == 'Title':
            value = 0.74
        elif token in {'#include', '<?', 'package'}:
            value = 0.69
        elif token == 'using':
            value = 0.61
        elif token in SOURCE_OPENINGS:
            value = 0.32
        elif token in {'//', '/*'}:
            value = 0.41
        elif token == '/**' or token.startswith('"""'):
            value = 0.30
        elif token in {'/*\n', '//\n', '#!/'}:
            value = 0.18
    return (doc, token), float(value)

programs.luna:
"""Approximate two recurring cues: can't, and marked document openings."""
READS = ()

# Heading, markup, and programming-language leaders seen at document starts.
DOCUMENT_LEADERS = {
    "#", "#include", "<?", "package", "using", "import",
    "Title", "/**", "/*", "//",
}
NEGATIVE_ENDINGS = {"'t", "’t", "n't", "n’t"}


def step(carry, prefix, upstream):
    """Predict the component's response to a negative contraction or code opener."""
    tokens = prefix.token_strings
    token = tokens[-1]
    if token in NEGATIVE_ENDINGS and len(tokens) > 1:
        if tokens[-2].strip().lower() == "can":
            return None, 0.56
    if len(tokens) > 1:
        starts_document = (
            prefix.document_ids[-1] != prefix.document_ids[-2]
            or tokens[-2] == "<|endoftext|>"
        )
        if starts_document and token in DOCUMENT_LEADERS:
            return None, 0.62
    return None, 0.0

programs.sol:
"""A partial, local phrase-transition explanation.

Selected commas, pronouns and prepositions after BE, FOR, TO and DO give
positive responses. DUE TO, ALONG WITH and several related fixed phrases
are negative. Word endings resembling these transitions (is-omorphic,
for-aging) also respond. Small offsets cover selected English function
words, chat delimiters, and document-initial tokens. Everything else is
zero. Two preceding tokens are remembered, reset for each document.
This captures local regularities, not most token-specific variation.
"""
READS = ()

# Responses at the end of linking-verb phrases, such as "is to" or "was in".
BE_ENDINGS = {
    ',': 0.36, 'to': 0.24, 'for': 0.27, 'with': 0.28,
    'in': 0.14, 'on': 0.15, 'at': 0.13, 'as': 0.17,
    'about': 0.08, 'of': 0.08, 'it': 0.21, 'you': 0.16,
    'this': 0.10, 'that': 0.06, 'then': 0.19, 'so': 0.14,
    'no': 0.11, 'and': 0.23, 'if': 0.25,
}
FOR_ENDINGS = {
    ',': 0.27, 'to': 0.33, 'for': 0.25, 'with': 0.38,
    'in': 0.37, 'on': 0.25, 'at': 0.28, 'as': 0.27,
    'about': 0.21, 'it': 0.31, 'you': 0.29, 'them': 0.30,
    'me': 0.17, 'him': 0.16, 'her': 0.12, 'us': 0.22,
    'this': 0.14, 'that': 0.12, 'some': 0.13, 'any': 0.09,
    'which': 0.09, 'their': 0.07, 'our': 0.05, 'other': 0.08,
    'being': 0.21, 'having': 0.13, 'and': 0.26, 'up': 0.25,
}
# Sparse lexical offsets, restricted to ordinary function words.
BASELINE = {
    'this': -0.037, 'that': -0.019, 'those': -0.063,
    'on': 0.023, 'under': -0.056, 'within': -0.052,
    'without': -0.053, 'only': 0.045, 'even': 0.051,
    'another': 0.055, 'some': -0.033, 'them': 0.044,
    'we': 0.021, 'will': 0.023, 'always': -0.073, 'never': -0.078,
}
INITIAL = {
    ' the': -0.127, ' The': -0.113, ' to': 0.191, ' is': 0.134,
    ' with': 0.167, ' on': 0.103, ' if': 0.161, 'If': 0.146,
    ' and': -0.10, ' this': -0.213, ' you': -0.122, 'You': -0.141,
    ' it': -0.067, ' ': -0.084, '<|im_start|>': -0.038,
}
MARKERS = {
    '<|im_end|>': 0.031, '<tool_call>': -0.065,
    '<think>': 0.022, '</think>': -0.066,
}
NEGATIVE_PHRASES = {
    ('due', 'to'): -0.15, ('pursuant', 'to'): -0.15,
    ('go', 'to'): -0.08, ('going', 'to'): -0.08,
    ('way', 'to'): -0.08, ('ways', 'to'): -0.08,
    ('along', 'with'): -0.14, ('together', 'with'): -0.14,
    ('up', 'with'): -0.14, ('known', 'as'): -0.12,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, earlier = ('', '') if first else carry[1:]
    prev = previous.strip().lower()
    word = token.strip().lower()
    # Distinguish leading-space word tokens from word-internal fragments.
    ending = word if token == ' ' + word else ''
    if token.startswith(','):
        ending = ','
    if previous.strip().isupper() and len(prev) > 1:
        prev = ''  # Do not confuse acronyms with function words.
    value = 0.0

    if prev in {'is', 'was', 'are', 'were', 'be', 'been', 'being'}:
        strength = 0.67 if prev in {'are', 'were'} else 1.0
        if prev in {'be', 'been', 'being'}:
            strength = 0.82
        if previous == prev:
            strength *= 0.25  # Bare fragments give weaker responses.
        value = strength * BE_ENDINGS.get(ending, 0.0)
    elif prev == 'for':
        value = FOR_ENDINGS.get(ending, 0.0)
        if previous.strip() == 'For' and ending in FOR_ENDINGS:
            value += 0.13
    elif prev == 'to':
        value = 0.60 * FOR_ENDINGS.get(ending, 0.0)
        if ending == ',':
            value = 0.225
    elif prev in {'do', 'does', 'did', 'doing', 'done'}:
        value = {'with': 0.43, 'in': 0.20, ',': 0.15}.get(ending, 0.0)
    elif ending == ',' and prev in {
        'can', 'could', 'may', 'might', 'must', 'will', 'would',
        'should', 'have', 'has', 'had', 'not',
    }:
        value = 0.21
    value = NEGATIVE_PHRASES.get((prev, ending), value)

    if ending == 'the' and prev in {'in', 'on', 'from', 'by', 'with'}:
        value = -0.02
    elif ending == 'a' and prev == 'with':
        value = -0.06
    elif previous.startswith(','):
        if ending in {'in', 'with', 'at', 'it', 'this', 'then'}:
            value = -0.06
        elif ending == 'the':
            value = 0.024
        elif ending == 'which':
            value = 0.037

    # Specific mathematical and foraging word completions.
    if token == 'omorphic' and prev == 'is':
        value = 0.62
    elif token == 'orphism' and prev == 'om' and earlier.strip().lower() == 'is':
        value = 0.48
    elif token in {'age', 'aging'} and prev == 'for':
        value = 0.43 if token == 'age' else 0.64
    elif token == 'ic' and prev == 'algebra':
        value = -0.33
    elif token == 'mic' and prev == 'logarith':
        value = -0.21

    if value == 0.0 and ending:
        value = BASELINE.get(word, 0.0)
    value = MARKERS.get(token, value)
    if first:
        value = INITIAL.get(token, value)
        if word == 'for':
            value = 0.51 if token == ' for' else 0.35
            if token == ' For':
                value = 0.45
    return (doc, token, previous), float(value)
